function AntiRagdollGroundGuard.nativeCarryActive(character)
if not character or player.Character ~= character then return false end
if character:GetAttribute("IsMinigame") == true then return true end
local carrierId = tonumber(character:GetAttribute("CarrierUserId"))
if carrierId and carrierId > 0 and carrierId ~= player.UserId then return true end
local humanoid = character:FindFirstChildOfClass("Humanoid")
local root = character:FindFirstChild("HumanoidRootPart")
for _, instance in ipairs({character, humanoid, root}) do
if instance and (instance:GetAttribute("IsCarried") == true
or instance:GetAttribute("IsCarrying") == true) then
