if now < (AntiRagdollGroundGuard.NextNativeImpactAt or 0) then return end
local velocity = root.AssemblyLinearVelocity
local horizontal = Vector3.new(velocity.X, 0, velocity.Z).Magnitude
if horizontal < ANTI_RAGDOLL_HORIZONTAL_KNOCKBACK then return end
