if part:IsA("BasePart") and not part.Anchored then
local current = part.AssemblyLinearVelocity
local speed = Vector3.new(current.X, 0, current.Z).Magnitude
if speed > ANTI_RAGDOLL_HORIZONTAL_KNOCKBACK then
local factor = 18 / speed
part.AssemblyLinearVelocity = Vector3.new(current.X * factor, current.Y, current.Z * factor) end end end end
