local requestFn = getRequestFunction() if not requestFn then
return nil, "HTTP indisponível no executor" end
maxPages = math.clamp(tonumber(maxPages) or 1, 1, 3) local placeId = game.PlaceId
local currentJobId = tostring(game.JobId or "" ) local cursor = nil local servers = {}
local seen = {} for _ = 1, maxPages do
local url = "https://games.roblox.com/v1/games/" .. tostring(placeId)
.. "/servers/Public?sortOrder=Asc&excludeFullGames=true&limit=100"
if cursor and cursor ~= "" then
url = url .. "&cursor=" .. HttpService:UrlEncode(cursor) end
local requestOk, response = pcall(function()
return requestFn({ Url = url, Method = "GET", Headers = { ["Accept"] = "application/json", }, }) end)
if not requestOk or type(response) ~= "table" then
return nil, "Falha na requisição" end
local statusCode = tonumber(response.StatusCode or response.Status or response.status or 0) or 0
if statusCode ~= 0 and (statusCode < 200 or statusCode >= 300) then
return nil, "API HTTP " .. tostring(statusCode) end
local body = response.Body or response.body or response.ResponseBody
if type(body) ~= "string" or body == "" then
return nil, "Resposta vazia da API" end
local decodeOk, decoded = pcall(HttpService.JSONDecode, HttpService, body)
if not decodeOk or type(decoded) ~= "table" then
return nil, "Resposta inválida da API" end for _, server in ipairs(decoded.data or {}) do
local id = tostring(server.id or "" ) local playing = tonumber(server.playing) or 0
local maxPlayers = tonumber(server.maxPlayers) or 0
if id ~= "" and id ~= currentJobId and not seen[id] and maxPlayers > 0 and playing >= 0
and playing < maxPlayers then
seen[id] = true
table.insert(servers, { id = id, playing = playing, maxPlayers = maxPlayers, ping =
tonumber(server.ping), fps = tonumber(server.fps), }) end end
cursor = decoded.nextPageCursor if not cursor or cursor == "" or #servers >= 160 then
break end end return servers end local function closeServerBrowser(animated)
ServerBrowserCache.browserToken += 1 ServerBrowserCache.loadToken += 1
