ServerBrowserCache.statusLabel = nil ServerBrowserCache.activeJoinButton = nil
ServerBrowserCache.activeJoinOriginalText = nil ServerBrowserCache.setBusyVisual = nil
if not previous or not previous.Parent then return end if not animated then
previous:Destroy() return end local main = previous:FindFirstChild("Main", true)
local dimmer = previous:FindFirstChild("Dimmer", true) if main then
local scale = main:FindFirstChildOfClass("UIScale") if scale then
TweenService:Create(scale, TweenInfo.new(0.16, Enum.EasingStyle.Quad,
Enum.EasingDirection.In), {Scale=math.max(0.4, scale.Scale*0.88)}):Play() end
