local function sortedCopy(servers) local result = {}
for _, server in ipairs(servers or {}) do
table.insert(result, server) end table.sort(result, function(a, b)
local aFree = math.max(0, (a.maxPlayers or 0) - (a.playing or 0))
local bFree = math.max(0, (b.maxPlayers or 0) - (b.playing or 0))
local aPing = tonumber(a.ping) or math.huge local bPing = tonumber(b.ping) or math.huge
if sortMode == "empty" then
if aFree ~= bFree then return aFree > bFree end return (a.playing or 0) < (b.playing or 0)
elseif sortMode == "ping" then
if aPing ~= bPing then return aPing < bPing end return aFree > bFree end
local aPenalty = aFree <= 1 and 1000 or 0 local bPenalty = bFree <= 1 and 1000 or 0
local aScore = aPenalty + aPing - math.min(aFree, 20) * 2.2
local bScore = bPenalty + bPing - math.min(bFree, 20) * 2.2
if aScore ~= bScore then return aScore < bScore end
return (a.playing or 0) < (b.playing or 0) end) return result end
