local function ballBehindRoot(root, position)
if not root or not position then return false end local delta = position - root.Position
local flat = Vector3.new(delta.X, 0, delta.Z) local forward = root.CFrame.LookVector
local flatForward = Vector3.new(forward.X, 0, forward.Z)
