sample.LastMeasured = measured sample.LastMeasuredAt = now end end
if rawVelocity.Magnitude > 0.15 then
sample.LastVelocity = rawVelocity sample.LastVelocityAt = now
elseif measuredValid then
sample.LastVelocity = measured sample.LastVelocityAt = now end
sample.Position, sample.Time = position, now
local stale = math.max(0, now - sample.LastMoved) local velocity = rawVelocity
if measuredValid and rawVelocity.Magnitude > 3 and measured.Magnitude > 3 and
measured:Dot(rawVelocity) < measured.Magnitude * rawVelocity.Magnitude * 0.15 then
velocity = measured
elseif velocity.Magnitude <= 0.12 and measuredValid then
velocity = measured end if velocity.Magnitude <= 0.12 and
