B.LastTarget = choice.Player if O.TargetLock then B.LockedTarget = choice.Player end end
return choice end local function curveParry(callback)
if not O.AutoCurve or os.clock() - B.LastCurve < O.CurveCooldown then
return callback() end local target = closestTarget()
if not target then return callback() end local nearbyCount = #Players:GetPlayers()
local chance = O.CurveChance + (nearbyCount <= 2 and O.CurveDuelBias or 0)
if RNG:NextNumber(0,100) > math.clamp(chance,0,100) then return callback() end
local camera = Workspace.CurrentCamera if not camera then return callback() end
local previous = camera.CFrame
local direction = target.Root.Position - camera.CFrame.Position
if direction.Magnitude < 0.01 then return callback() end B.LastCurve = os.clock()
pcall(function() camera.CFrame = CFrame.lookAt(previous.Position, target.Root.Position) end)
local ok = callback() task.defer(function()
if camera and camera.Parent and camera.CameraType ~= Enum.CameraType.Scriptable then
pcall(function() camera.CFrame = previous end) end end) return ok end
local behindAimStepName = "UnicornHubBladeBall360_" .. tostring(player.UserId)
local function clearBehindAim(restore) B.BehindAimToken = (B.BehindAimToken or 0) + 1
pcall(function() RunService:UnbindFromRenderStep(behindAimStepName) end)
local state = B.BehindAim B.BehindAim = nil if not restore or not state then return end
local camera = state.Camera if not camera or camera ~= Workspace.CurrentCamera or
camera.CameraType == Enum.CameraType.Scriptable then return end
local aimed = state.LastAim
if aimed and camera.CFrame.LookVector:Dot(aimed.LookVector) < 0.92 then return end
pcall(function()
camera.CFrame = CFrame.new(camera.CFrame.Position) * state.Original.Rotation end) end
local function aimBehindBall(camera, ballPosition) if not camera or not ballPosition or
camera ~= Workspace.CurrentCamera or
camera.CameraType == Enum.CameraType.Scriptable then return false end
local state = B.BehindAim if not state or state.Camera ~= camera then
if state then clearBehindAim(false) end
state = { Camera = camera, Original = camera.CFrame,
Target = ballPosition, LastAim = nil } B.BehindAim = state local bound = pcall(function()
RunService:BindToRenderStep(behindAimStepName,
Enum.RenderPriority.Camera.Value + 1, function() local active = B.BehindAim
if not active or not B.Running or not State.Running or
active.Camera ~= Workspace.CurrentCamera or
active.Camera.CameraType == Enum.CameraType.Scriptable then
clearBehindAim(false) return end local current = active.Camera.CFrame
if (active.Target - current.Position).Magnitude < 0.1 then return end
active.LastAim = CFrame.lookAt(current.Position, active.Target)
active.Camera.CFrame = active.LastAim end) end) if not bound then
B.BehindAim = nil return false end end state.Target = ballPosition pcall(function()
local current = camera.CFrame if (ballPosition - current.Position).Magnitude > 0.1 then
state.LastAim = CFrame.lookAt(current.Position, ballPosition)
camera.CFrame = state.LastAim end end) B.BehindAimToken = (B.BehindAimToken or 0) + 1
local token = B.BehindAimToken task.delay(0.10, function()
if token == B.BehindAimToken then clearBehindAim(true) end end) return true end
local function parry(source, ball, ballPosition, root) local now = os.clock()
local spam = source == "lobbySpam" or source == "arenaSpam" or
source == "spam" or source == "fastSpam" or source == "lobbyFastSpam"
local rescue = source == "seguranca" or source == "lobbySafety"
local interval = rescue and 0.055 or
((source == "fastSpam" or source == "lobbyFastSpam") and
0.064 or (spam and 0.10 or 0.073)) local debounce = rescue and 0.049 or 0.062
if now - B.LastParryAt < debounce then return false end
if O.CooldownProtection and now - B.LastParry < interval then return false end
local method = "Indisponivel" local mouseX, mouseY = nil, nil local function send()
if O.ParryMethod == "Remote" then
local remote = findRemote("ParryButtonPress") if remote and remote:IsA("RemoteEvent") then
method = "RemoteEvent" return pcall(function() remote:FireServer() end)
elseif remote and remote:IsA("BindableEvent") then
method = "BindableEvent" return pcall(function() remote:Fire() end) end end
local isLobbyClick = source == "lobby" or source == "lobbySpam" or
source == "lobbySafety" or source == "lobbyFastSpam" if rescue then
method = "Segunda tentativa (F)" if pressKey(Enum.KeyCode.F) then return true end end
if isLobbyClick or O.ParryMethod == "Mouse" then
method = isLobbyClick and "Clique de treino" or "Clique virtual"
if pressMouse(mouseX, mouseY) then return true end end method = "Tecla F simulada"
return pressKey(Enum.KeyCode.F) end
local behind = O.BehindParry and ballBehindRoot(root, ballPosition) local ok
if behind and (source == "arena" or source == "lobby" or
source == "arenaSpam" or source == "lobbySpam" or
source == "fastSpam" or source == "lobbyFastSpam" or
source == "spam" or source == "seguranca" or
source == "lobbySafety") then
local camera = Workspace.CurrentCamera
if camera and ballPosition and aimBehindBall(camera, ballPosition) then
mouseX = camera.ViewportSize.X * 0.5 mouseY = camera.ViewportSize.Y * 0.5
B.LastBehindAimAt = now end ok = send()
else
ok = curveParry(send) end B.LastParryAt = now B.LastParryMethod = method if ok then
B.LastParry = now B.LastState = "Tentativa de parry (" .. source .. ")" return true end
debugMsg("Tentativa de parry falhou: " .. method) return false end
local function effectVisible(name)
return activeEffects[name] and os.clock() - activeEffects[name] < 1.25 end
local effectNames = {
Infinity = {"infinity"}, DeathSlash = {"deathslash", "death slash"},
TimeHole = {"timehole", "time hole"}, Pull = {"blackholepull", "pull"},
Singularity = {"singularity"}, Slashes = {"slashes", "slashattack"},
Forcefield = {"forcefield", "force field"}, Phantom = {"phantom", "fakeball", "fake ball"},
} local function scanEffects(ball)
local scanAbilityEffects = O.InfinityDetection or O.DeathSlashDetection or
O.TimeHoleDetection or O.PullDetection or
O.SingularityDetection or O.SlashesDetection or
O.ForcefieldDetection if not scanAbilityEffects and
(not O.AntiPhantom or not ball or ball:GetAttribute("realBall") == true) then
return end if os.clock() - B.LastScan < 0.40 then return end B.LastScan = os.clock()
local inspected = 0 local function testObject(item) if inspected > 250 then return end
inspected += 1 local name = string.lower(item.Name)
for effect, words in pairs(effectNames) do
for _, word in ipairs(words) do
if string.find(name, word, 1, true) then
activeEffects[effect] = os.clock() break end end end end if ball then
testObject(ball) for attrName, attr in pairs(ball:GetAttributes()) do
if attr == true then testObject({Name=attrName}) end end end local folders = {}
for _, name in ipairs({"Effects", "Projectiles", "Balls"}) do
local folder = Workspace:FindFirstChild(name)
if folder then table.insert(folders, folder) end end for _, folder in ipairs(folders) do
if folder then
for _, item in ipairs(folder:GetDescendants()) do
testObject(item) if inspected > 250 then break end end end end
local char = player.Character if char then
for _, item in ipairs(char:GetChildren()) do testObject(item) end
for key,value in pairs(char:GetAttributes()) do
if value == true then testObject({Name=key}) end end end end
local function pauseForAbility()
if O.InfinityDetection and effectVisible("Infinity") then return true, "Infinity" end
if O.TimeHoleDetection and effectVisible("TimeHole") then return true, "Time Hole" end
if O.SingularityDetection and effectVisible("Singularity") then return true, "Singularity" end
if O.ForcefieldDetection and effectVisible("Forcefield") then return true, "Forcefield" end
return false end local function removeBladeBallOverlay() if B.Hud then
pcall(function() B.Hud:Destroy() end) B.Hud = nil end
local oldOverlay = playerGui:FindFirstChild("UnicornHubBladeBallHUD") if oldOverlay then
oldOverlay:Destroy() end B.HudFrame = nil B.HudAccent = nil B.HudStroke = nil
B.Labels.Hud = nil B.LastHudSnapshot = nil end removeBladeBallOverlay()
local function ballGateFor(ball, targeted, distance, signedApproach, now)
if not ball then return nil end local gate = ballParryGates[ball] if not gate then
gate = { Armed = true, LastDistance = distance, SafetyRetryCount = 0 }
ballParryGates[ball] = gate end if not gate.Armed then
if not targeted then
gate.TargetLostAt = gate.TargetLostAt or now end
local deltaDistance = distance - (gate.LastDistance or distance)
if now - (gate.ShotAt or 0) >= 0.035 and
((signedApproach < -0.8 and deltaDistance >= -0.12) or
deltaDistance >= math.max(0.12, distance * 0.004)) then
gate.WentOut = true end if gate.WentOut then
gate.Farthest = math.max(gate.Farthest or distance, distance) end
local returned = gate.WentOut and targeted and
signedApproach > 0.6 and
(distance < (gate.Farthest or distance) - 0.08 or
deltaDistance < -0.12) local targetCameBack = targeted and gate.TargetLostAt and
now - gate.TargetLostAt >= 0.025 and signedApproach > 0.6
if now - (gate.ShotAt or 0) >= 0.075 and
(returned or targetCameBack) then
gate.Armed = true gate.WentOut = false gate.TargetLostAt = nil gate.FastSpamCount = 0
gate.SafetyRetryCount = 0 end end gate.LastDistance = distance return gate end
local function observePullRedirection(ball, kind, targeted, velocity, distance, now)
if not ball or kind ~= "ARENA" then return false, false end local explicitTarget = nil
for _, name in ipairs({"target", "Target", "TargetPlayer", "TargetName", "targetName", "TargetUserId"}) do
local value = ball:GetAttribute(name) if value ~= nil then
explicitTarget = tostring(value) break end end local observation = ballPullHistory[ball]
if not observation then
observation = { Targeted = targeted, Target = explicitTarget,
LastSeen = now, RedirectUntil = 0 } ballPullHistory[ball] = observation
return false, false end local newlyTargeted = targeted and not observation.Targeted
local changedTarget = targeted and explicitTarget ~= nil and
observation.Target ~= nil and explicitTarget ~= observation.Target
local fresh = now - (observation.LastSeen or now) <= 0.30
local redirected = O.PullDetection and (newlyTargeted or changedTarget) and
fresh and distance < 300 if redirected then
observation.RedirectUntil = now + 0.40 debugMsg("Pull: bola mudou de alvo em sua direcao")
elseif not targeted then
observation.RedirectUntil = 0 end observation.Targeted = targeted
observation.Target = explicitTarget observation.LastSeen = now
local active = O.PullDetection and targeted and now < observation.RedirectUntil
return active == true, redirected == true end local function markBallShot(gate)
if gate then
gate.Armed = false gate.ShotAt = os.clock() gate.FastSpamCount = 0
gate.SafetyRetryCount = 0 gate.WentOut = false gate.Farthest = gate.LastDistance or 0
gate.TargetLostAt = nil end end local function heartbeat(dt)
if not State.Running or not B.Running or not State.IsBladeBall then return end
local now = os.clock() if now - B.LastLogicAt < 0.008 then return end B.LastLogicAt = now
local character, humanoid, root = characterParts() if not root then return end
local ball, ballKind = getBall(root)
local velocity = ball and getVelocity(ball) or Vector3.zero
local ballPosition = ball and ball.Position or nil local lagStatus, lagStale = "--", 0
if ball then
velocity, ballPosition, lagStatus, lagStale = lagBallMotion(ball, velocity, now) end
local distance = ball and (ballPosition - root.Position).Magnitude or 999
local speed = velocity.Magnitude
local toward = (ball and distance > 0.01) and (root.Position - ballPosition).Unit or Vector3.zero
local playerVelocity = root.AssemblyLinearVelocity
local airborne = humanoid.FloorMaterial == Enum.Material.Air
local safePlayerVelocity = Vector3.new(
math.clamp(playerVelocity.X, -32, 32),
math.clamp(playerVelocity.Y, airborne and -14 or -30,
airborne and 14 or 30),
math.clamp(playerVelocity.Z, -32, 32))
local ballApproach = ball and velocity:Dot(toward) or 0
local relativeClosing = ball and (velocity - safePlayerVelocity):Dot(toward) or 0
local closing = math.max(0, relativeClosing, ballApproach * 0.92)
local tti = closing > 0.02 and distance / closing or 999
local lobbySignedApproach = ball and velocity:Dot(toward) or 0
local lobbyApproach = math.max(0, lobbySignedApproach)
local contactRadius = ball and math.clamp(
(ball.Size.Magnitude + root.Size.Magnitude) * 0.5 +
(airborne and 2.6 or 1.7), 4.5, airborne and 12 or 10
) or 4.5 local arenaContactRadius = contactRadius +
math.clamp(tonumber(O.ParryEarlyDistance) or 3, 0, 8)
local lobbyTimeToContact = lobbyApproach > 0.02 and
math.max(0, distance - contactRadius) / lobbyApproach or 999
local arenaTimeToContact = closing > 0.02 and speed > 0.5 and
math.max(0, distance - arenaContactRadius) / closing or 999 local predictedContact = 999
if ball and speed > 1 and closing > 0.2 then
local travel = root.Position - ballPosition local relative = velocity - safePlayerVelocity
local magnitude2 = relative:Dot(relative) if magnitude2 > 4 then
local interceptAt = math.clamp(travel:Dot(relative) / magnitude2, 0, 0.65)
local miss = (travel - relative * interceptAt).Magnitude
if miss <= arenaContactRadius + (airborne and 5 or 3.5) then
predictedContact = interceptAt end end end
arenaTimeToContact = math.min(arenaTimeToContact, predictedContact) local ping = 0
if O.PingCompensation then
if now - B.LastPingCheck >= 0.30 then
B.LastPingCheck = now
local ok, measured = pcall(function() return player:GetNetworkPing() * 1000 end)
if ok and type(measured) == "number" then
B.CachedPing = math.clamp(measured, 0, 350) end end ping = B.CachedPing end
local targeted = isTargeted(ball, character)
B.BehindBall = ballBehindRoot(root, ballPosition)
if not targeted and ballKind == "ARENA" and ball and speed > 1 then
local explicitTarget = false
for _, key in ipairs({"target", "Target", "TargetPlayer", "TargetName", "targetName", "TargetUserId"}) do
if ball:GetAttribute(key) ~= nil then
explicitTarget = true break end end if not explicitTarget then
local toMe = root.Position - ballPosition
local predictedTime = toMe:Dot(velocity) / (speed * speed)
if predictedTime > 0 and predictedTime <= 3.25 then
local missDistance = (toMe - velocity * predictedTime).Magnitude
local tolerance = contactRadius + math.clamp(predictedTime * 1.4, 3.5, 7)
if missDistance <= tolerance then
targeted = true end end end end if ball ~= B.LastBall then
B.SlashParries, B.JumpUses = 0, 0 end
local pullRedirect, pullNewTarget = observePullRedirection(
ball, ballKind, targeted, velocity, distance, now)
B.PullStatus = not O.PullDetection and "OFF" or
(pullRedirect and "REDIRECIONANDO" or
(targeted and "ALVO ESTAVEL" or "AGUARDANDO ALVO")) scanEffects(ball)
if O.AntiPhantom and effectVisible("Phantom") and ball and ball:GetAttribute("realBall") ~= true then
targeted = false end
local activeGate = ballGateFor(ball, targeted, distance, lobbySignedApproach, now)
if pullNewTarget and activeGate and not activeGate.Armed and
now - (activeGate.ShotAt or 0) >= 0.085 then
activeGate.Armed = true activeGate.WentOut = false activeGate.TargetLostAt = nil
activeGate.FastSpamCount = 0 activeGate.SafetyRetryCount = 0 end
B.BallGateStatus = activeGate and (activeGate.Armed and "PRONTO" or
(activeGate.WentOut and "AGUARDANDO VOLTA" or "AGUARDANDO SAIDA")) or "--"
local paused, reason = pauseForAbility()
local danger = targeted and ball and closing > 0.5 and distance < 140
local delayTime = O.DeathSlashDetection and effectVisible("DeathSlash") and 0.08 or 0
if O.SlashesDetection and effectVisible("Slashes") then
delayTime += O.SlashesParryDelay / 1000 if now - B.SlashWindow > 1.5 then
B.SlashWindow = now B.SlashParries = 0 end end
local requiredTime = 0.11 + (100 - O.ParryAccuracy) * 0.0019 + (ping / 1000 * 0.6)
if pullRedirect then requiredTime += 0.065 end local lagLead = O.LagBall and
(lagStatus == "PREVISAO" and O.LagBallMargin / 1000 or 0.025) or 0
local pullEstimate = pullRedirect and speed > 0.5 and
distance <= math.min(90, contactRadius + speed * 0.45)
local arenaApproach = math.max(lobbyApproach,
pullEstimate and speed * 0.78 or 0) local arenaClosing = math.max(closing,
pullEstimate and speed * 0.78 or 0) if pullEstimate and arenaClosing > 0.02 then
arenaTimeToContact = math.max(0, distance - arenaContactRadius) / arenaClosing end
local accuracyLead = math.clamp((100 - O.ParryAccuracy) * 0.0016, 0, 0.14)
local highSpeedLead = math.clamp((speed - 120) / 2200, 0, 0.18)
local airborneLead = airborne and math.clamp(0.026 + math.abs(playerVelocity.Y) / 1800,
0.026, 0.075) or 0 local lobbyLead = math.clamp(requiredTime + 0.11 + lagLead, 0.30, 0.59)
local arenaBaseLead = 0.143 + accuracyLead +
ping / 1000 * 0.78 + lagLead + highSpeedLead + airborneLead +
(pullRedirect and 0.055 or 0) - delayTime
local arenaLead = math.clamp(math.max(arenaBaseLead,
lobbyLead - 0.025 + airborneLead * 0.5 - delayTime), 0.18, 0.54)
local arenaRange = math.clamp(arenaContactRadius +
math.max(arenaApproach, arenaClosing) * arenaLead * 1.10, 18, 800)
local arenaCanParry = ballKind == "ARENA" and targeted and not paused and
speed > 0.5 and arenaApproach > 0.02 and arenaClosing > 0.02 and
distance <= arenaRange and arenaTimeToContact <= arenaLead
local lobbyRange = math.max(19, math.min(58,
contactRadius + lobbyApproach * lobbyLead))
local lobbyCanParry = O.LobbyParry and ballKind == "LOBBY" and
targeted and not paused and lobbyApproach > 0.02 and
distance <= lobbyRange and lobbyTimeToContact <= lobbyLead
local allowSlash = not (O.SlashesDetection and effectVisible("Slashes") and
B.SlashParries >= O.SlashesMaxParry)
if paused then B.LastState = "Habilidade detectada: " .. reason end
local autoEnabled = O.AutoParry or (O.LobbyParry and ballKind == "LOBBY")
local autoReady = activeGate and activeGate.Armed if allowSlash and autoReady and
((autoEnabled and (arenaCanParry or lobbyCanParry)) or
(O.Triggerbot and targeted and closing > 0 and distance <= 16)) then
if parry(ballKind == "LOBBY" and "lobby" or "arena", ball, ballPosition, root) then
markBallShot(activeGate) B.SlashParries += 1 end end
local manualSpamActive = O.ManualSpam and B.ManualHeld and
(ball ~= nil or O.LobbyParry) local autoSpamActive = O.AutoSpam and danger and
(tti <= 0.55 or distance <= 34)
if (manualSpamActive or autoSpamActive) and (autoReady or manualSpamActive) then
local spamSource = ballKind == "LOBBY" and "lobbySpam" or "arenaSpam"
if allowSlash and parry(spamSource, ball, ballPosition, root) then
if not manualSpamActive then markBallShot(activeGate) end B.SlashParries += 1 end end
local safetyRetryWindow = math.clamp(0.13 + ping / 1000 * 0.45 +
(airborne and 0.035 or 0), 0.13, 0.23)
local safetyInLobby = ballKind == "LOBBY" and O.LobbyParry
local safetyInArena = ballKind == "ARENA" and O.AutoParry
local safetyApproach = safetyInLobby and lobbyApproach or arenaApproach
local safetyClosing = safetyInLobby and lobbyApproach or arenaClosing
local safetyTimeToContact = safetyInLobby and lobbyTimeToContact or arenaTimeToContact
local safetyRetry = O.SecondChanceParry and (safetyInLobby or safetyInArena) and
not (O.FastBallSpam and speed >= O.FastBallSpeed) and
targeted and not paused and allowSlash and
activeGate and not activeGate.Armed and not activeGate.WentOut and
(activeGate.SafetyRetryCount or 0) < 1 and
now - (activeGate.ShotAt or 0) >= 0.065 and
now - (activeGate.ShotAt or 0) <= 0.34 and
speed > 0.15 and safetyApproach > 0.10 and safetyClosing > 0.10 and
safetyTimeToContact <= safetyRetryWindow and
distance <= contactRadius + safetyClosing * (safetyRetryWindow + 0.045)
if safetyRetry then
activeGate.SafetyRetryCount = 1 if parry(safetyInLobby and "lobbySafety" or "seguranca",
ball, ballPosition, root) then
B.SlashParries += 1 end end local fastSpamEligible = O.FastBallSpam and
((ballKind == "ARENA" and O.AutoParry and arenaCanParry) or
(ballKind == "LOBBY" and O.LobbyParry and lobbyCanParry)) and
allowSlash and speed >= O.FastBallSpeed B.FastSpamActive = fastSpamEligible == true
if fastSpamEligible and activeGate and not activeGate.Armed and
not activeGate.WentOut and
now - (activeGate.ShotAt or 0) <= 0.38 and
(activeGate.FastSpamCount or 0) < 3 then
local fastSource = ballKind == "LOBBY" and "lobbyFastSpam" or "fastSpam"
if parry(fastSource, ball, ballPosition, root) then
activeGate.FastSpamCount = (activeGate.FastSpamCount or 0) + 1 B.SlashParries += 1 end end
if O.AutoAbility and danger and speed >= O.MinBallSpeed and tti < 0.6 and
now - B.LastAbility >= (O.CooldownProtection and 8 or 1.2) then
local remote = findRemote("AbilityButtonPress") local ok = false
if remote and remote:IsA("RemoteEvent") then
ok = pcall(function() remote:FireServer() end)
elseif remote and remote:IsA("BindableEvent") then
ok = pcall(function() remote:Fire() end)
else
ok = pressKey(Enum.KeyCode.Q) end if ok then B.LastAbility = now end end
if danger and O.AutoMove and distance < 44 and now - B.LastMove > 0.11 and
not humanoid.Sit and humanoid:GetState() ~= Enum.HumanoidStateType.Physics then
B.LastMove = now local sideways = Vector3.new(-toward.Z, 0, toward.X)
humanoid:Move(sideways, false) end if danger and O.Jumps > 0 and B.JumpUses < O.Jumps and
distance < 48 and now - B.LastJump > 1 then
B.LastJump = now B.JumpUses += 1 humanoid.Jump = true end sampleVelocity(ball) end
function B.set(key, value) if O[key] == nil then return end
if key == "BallDebugHUD" or key == "SpamIndicator" then
O[key] = false removeBladeBallOverlay() return end O[key] = value
if key == "TargetLock" and not value then B.LockedTarget = nil end
if key == "ManualSpam" and not value then B.ManualHeld = false end
if key == "BehindParry" and not value then clearBehindAim(true) end
if key == "LobbyParry" and not value then
for trackedBall in pairs(ballParryGates) do
if trackedBall.Parent == Workspace:FindFirstChild("TrainingBalls") then
ballParryGates[trackedBall] = nil end end end if not B.Connection and B.Running then
B.Connection = RunService.Heartbeat:Connect(heartbeat) end end function B.stop()
B.Running = false clearBehindAim(true)
if B.Connection then B.Connection:Disconnect() B.Connection = nil end
for _, connection in ipairs(B.Connections) do
pcall(function() connection:Disconnect() end) end table.clear(B.Connections)
removeBladeBallOverlay() B.ManualHeld = false table.clear(ballParryGates)
table.clear(ballLagHistory) table.clear(ballPullHistory) end
table.insert(B.Connections, UserInputService.InputBegan:Connect(function(input, processed)
if processed or not B.Running or not O.ManualSpam or
UserInputService:GetFocusedTextBox() then return end
if input.KeyCode == Enum.KeyCode.E then B.ManualHeld = true end end))
table.insert(B.Connections, UserInputService.InputEnded:Connect(function(input)
if input.KeyCode == Enum.KeyCode.E then B.ManualHeld = false end end))
table.insert(B.Connections, player.CharacterAdded:Connect(function() clearBehindAim(false)
B.LastLogicAt, B.LastPingCheck = 0, 0
B.LastBall, B.LastBallPosition, B.LastBallAt = nil, nil, 0
B.JumpUses, B.SlashParries, B.LockedTarget = 0, 0, nil table.clear(ballParryGates)
table.clear(ballLagHistory) table.clear(ballPullHistory) end))
function B.buildPage(page, makeSection, toggle, numeric, action, info)
local function t(title,key) toggle(page, title, "", function() return O[key] == true end,
