numeric(page,title,"",function() return true end,function() end,
function() return O[key] end,
function(v) B.set(key,math.clamp(tonumber(v) or minimum,minimum,maximum)) end,
minimum,maximum) end makeSection(page,"COMBAT > Parry","") t("Auto Parry", "AutoParry")
