if name == "safehouse" or name == "safehousebuilding" then
return "SAFE HOUSE", Color3.fromRGB(124, 230, 178)
elseif name == "powerstation" or name == "powerplant" then
return "ENERGIA", Color3.fromRGB(255, 221, 118)
elseif name == "observationtower" or name == "watchtower" then
return "TORRE", Color3.fromRGB(157, 198, 255)
elseif name == "basecamp" then
return "ACAMPAMENTO", Color3.fromRGB(170, 224, 255)
elseif name == "shop" or name == "merchantshop" then
return "LOJA", Color3.fromRGB(232, 190, 255) end end if R.Options.Supplies then
local isScrap = (name == "scrap" or name == "scrapmetal" or name == "scrappile"
