or string.match(name, "^scrappile%d+$") or name == "scrappickup") if isScrap then
local parentModel = instance.Parent
if instance:IsA("BasePart") and parentModel and parentModel:IsA("Model") then
local parentName = string.lower(parentModel.Name):gsub("[%s_%-]", "")
if parentName == name then return nil end end local parent = instance.Parent
while parent and parent ~= workspace do
if parent:IsA("Model") and isPlayerCharacter(parent) then return nil end
parent = parent.Parent end return "SUCATA", Color3.fromRGB(245, 205, 140), "scrap" end
local isFlareGun = (name == "flaregun" or name == "flairgun"
or name == "flarepistol" or name == "flarelauncher"
or name == "flaregunpickup" or name == "flaregunspawn"
or string.match(name, "^flaregun%d+$")
or string.match(name, "^flaregunpickup%d+$")) if isFlareGun then
local parentModel = instance.Parent
if instance:IsA("BasePart") and parentModel and parentModel:IsA("Model") then
