local function scanWorld() if not State.Running or not R.Running then return end
local wantsRake = R.Options.Warning or (R.Options.RakeEsp and State.ViewEspEnabled)
local wantsItems = R.Options.Supplies and State.ViewEspEnabled == true
local wantsMarkers = R.Options.Locations or wantsItems
if not wantsRake and not wantsMarkers then
currentRake = nil R.Target = nil R.ScrapFound = 0 R.FlareFound = 0 dropHighlight()
for target in pairs(R.Markers) do dropMarker(target) end return end local candidate = nil
local seen = {} local marked = 0 local scrapsFound = 0 local flaresFound = 0
for _, item in ipairs(workspace:GetDescendants()) do
if wantsRake and not candidate and item:IsA("Model") then
local name = string.lower(item.Name):gsub("[%s_%-]", "")
if (name == "rake" or name == "therake" or name == "rakenpc"
or name == "rakemonster" or name == "monster")
and item:FindFirstChildOfClass("Humanoid") and not isPlayerCharacter(item) then
candidate = item end end if wantsMarkers and marked < 45 then
local title, color, iconKind = pickMarker(item)
if title and targetPart(item) and (iconKind ~= "scrap" or wantsItems) then
marked += 1 if iconKind == "scrap" then scrapsFound += 1 end
if iconKind == "flaregun" then flaresFound += 1 end seen[item] = true
addMarker(item, title, color, iconKind) end end end R.ScrapFound = scrapsFound
R.FlareFound = flaresFound currentRake = candidate R.Target = candidate
createHighlight(candidate) for target in pairs(R.Markers) do
if not seen[target] or not target.Parent then dropMarker(target) end end end
