local function staminaCap(obj, current) local function readCap(parent)
if not parent then return nil end for _, key in ipairs(staminaMaxKeys) do
local amount = parent:GetAttribute(key)
if type(amount) == "number" and amount > 0 then return amount end
local sibling = parent:FindFirstChild(key)
if sibling and (sibling:IsA("NumberValue") or sibling:IsA("IntValue"))
and sibling.Value > 0 then
return sibling.Value end end return nil end
local cap = readCap(obj) or readCap(obj.Parent)
or readCap(player.Character) or readCap(player)
if not cap then cap = current <= 1 and 1 or 100 end return math.clamp(cap, 0, 100000) end
local STAMINA_WALKSPEED = 25
local staminaSpeed = {Humanoid = nil, Original = nil, Connection = nil, Writing = false}
local function releaseStaminaSpeed() if staminaSpeed.Connection then
staminaSpeed.Connection:Disconnect() staminaSpeed.Connection = nil end
local humanoid, original = staminaSpeed.Humanoid, staminaSpeed.Original
staminaSpeed.Humanoid, staminaSpeed.Original = nil, nil
if humanoid and humanoid.Parent and type(original) == "number"
and humanoid.Health > 0
and math.abs(humanoid.WalkSpeed - STAMINA_WALKSPEED) < 0.2 then
pcall(function() UnicornHubHumanoidWrites.set(humanoid, "WalkSpeed", original) end) end end
local function lockStaminaSpeed()
if not R.Running or not R.Options.InfiniteStamina then return end
local character = player.Character
local humanoid = character and character:FindFirstChildOfClass("Humanoid")
if not humanoid or humanoid.Health <= 0 then return end
if humanoid ~= staminaSpeed.Humanoid then
releaseStaminaSpeed() staminaSpeed.Humanoid = humanoid
staminaSpeed.Original = humanoid.WalkSpeed
staminaSpeed.Connection = humanoid:GetPropertyChangedSignal("WalkSpeed"):Connect(function()
if not R.Running or not R.Options.InfiniteStamina
or player.Character ~= character or staminaSpeed.Writing
or humanoid.Health <= 0 then return end
if math.abs(humanoid.WalkSpeed - STAMINA_WALKSPEED) > 0.05 then
staminaSpeed.Writing = true
pcall(function() UnicornHubHumanoidWrites.set(humanoid, "WalkSpeed", STAMINA_WALKSPEED) end)
staminaSpeed.Writing = false end end) end
if math.abs(humanoid.WalkSpeed - STAMINA_WALKSPEED) > 0.05 then
staminaSpeed.Writing = true
pcall(function() UnicornHubHumanoidWrites.set(humanoid, "WalkSpeed", STAMINA_WALKSPEED) end)
staminaSpeed.Writing = false end end local function refreshStamina()
if not R.Options.InfiniteStamina then return end lockStaminaSpeed()
local character = player.Character local now = os.clock()
if R.StaminaCharacter ~= character or now - R.StaminaScannedAt > 1.5 then
R.StaminaScannedAt = now R.StaminaCharacter = character table.clear(R.StaminaTargets)
local seen = {} local function inspect(obj) if not obj or seen[obj] then return end
seen[obj] = true
if obj:IsA("Tool") or obj:FindFirstAncestorOfClass("Tool") then return end
local isValue = obj:IsA("NumberValue") or obj:IsA("IntValue")
if isValue and isStaminaKey(obj.Name) then
table.insert(R.StaminaTargets, {obj = obj, value = true}) end
if obj == player or obj == character or obj:IsA("Humanoid")
or obj:IsA("Folder") or obj:IsA("Configuration") then
local ok, attrs = pcall(function() return obj:GetAttributes() end) if ok then
for key, amount in pairs(attrs) do
if type(amount) == "number" and isStaminaKey(key) then
table.insert(R.StaminaTargets, {obj = obj, attribute = key}) end end end end end
inspect(player) inspect(character) local roots = {} for _, root in pairs({
scripts = player:FindFirstChild("PlayerScripts"),
gui = player:FindFirstChild("PlayerGui"),
character = character,
backpack = player:FindFirstChild("Backpack")
}) do
if root then table.insert(roots, root) end end for _, root in ipairs(roots) do
inspect(root) local inspected = 0 for _, obj in ipairs(root:GetDescendants()) do
inspect(obj) inspected += 1 if inspected >= 2200 then break end end end end
local count, active = 0, 0 for _, target in ipairs(R.StaminaTargets) do
local obj = target.obj if obj and obj.Parent then
local value = target.value and obj.Value or obj:GetAttribute(target.attribute)
if type(value) == "number" and value >= 0 then
count += 1 local cap = staminaCap(obj, value) if cap > value + 0.01 then
local ok = pcall(function() if target.value then
obj.Value = cap
else
obj:SetAttribute(target.attribute, cap) end end)
if ok then active += 1 end end end end end R.StaminaCount = count if count > 0 then
R.StaminaMessage = "Local: " .. tostring(count) .. " valor(es); reajustes: "
.. tostring(active) .. " (servidor pode limitar)"
else
R.StaminaMessage = "Sem stamina replicada; controle pode ser interno ao jogo" end end
