local function updateHud() local needsHud = R.Options.Warning or R.Options.Compass
if not needsHud then
if R.Hud then R.Hud:Destroy() end R.Hud, R.HudTitle, R.HudBody = nil, nil, nil
else
ensureHud() end local root = localRoot() local part = targetPart(currentRake)
local distance = (root and part) and (root.Position - part.Position).Magnitude or nil
local isNear = R.Options.Warning and distance and distance <= 125
local header = isNear and "THE RAKE · PERIGO PROXIMO" or "THE RAKE · MONITOR"
local line = "" if R.Options.Warning then
line = isNear and "ALERTA: o Rake esta perto!"
or "Alerta de proximidade ligado" end if R.Options.Compass then
local camera = workspace.CurrentCamera local look = camera and camera.CFrame.LookVector
local bearing = look and ((math.deg(math.atan2(look.X, -look.Z)) + 360) % 360) or 0
local dirs = {"N", "NE", "L", "SE", "S", "SO", "O", "NO"}
local direction = dirs[math.floor((bearing + 22.5) / 45) % 8 + 1]
line ..= (line ~= "" and "\n" or "") .. "Bussola: " .. direction
