State.getCandieContactParts = function(item) local parts = {} if not item then
return parts end local found = 0 local function consider(part)
if not part or not part:IsA("BasePart") or not part.Parent then
return end local size = part.Size local maxSide = math.max(size.X, size.Y, size.Z)
local name = string.lower(part.Name) local score = 0
if part:FindFirstChildOfClass("TouchTransmitter") or part:FindFirstChild("TouchInterest") then
score += 1000 end
if part:FindFirstChildWhichIsA("ProximityPrompt") or part:FindFirstChildWhichIsA("ClickDetector") then
score += 600 end
if string.find(name, "candy", 1, true) or string.find(name, "collect", 1, true)
or string.find(name, "pickup", 1, true) or string.find(name, "trigger", 1, true)
or string.find(name, "hitbox", 1, true) then
score += 240 end if part.CanTouch then score += 70 end
if not part.CanCollide then score += 65 end if maxSide <= 7 then score += 95 end
if maxSide >= 16 then score -= 160 end if maxSide >= 30 then score -= 230 end
if part.Transparency < 0.95 then score += 10 end found += 1
parts[#parts + 1] = { Part = part, Score = score, Order = found } end
if item:IsA("BasePart") then
consider(item)
elseif item:IsA("Model") then
for _, part in ipairs(item:GetDescendants()) do
if part:IsA("BasePart") then
consider(part) end end end table.sort(parts, function(a, b) if a.Score ~= b.Score then
return a.Score > b.Score end return a.Order < b.Order end) local result = {}
for i = 1, math.min(#parts, 8) do
result[i] = parts[i].Part end return result end
State.getCandieCandidates = function(folder) local candidates = {} if not folder then
return candidates end for _, item in ipairs(folder:GetDescendants()) do
if #candidates >= 250 then
break end
if string.lower(item.Name) == "candytemplate" and (item:IsA("Model") or item:IsA("BasePart")) then
local parent = item.Parent local insideAnotherCandy = false
while parent and parent ~= folder do
if string.lower(parent.Name) == "candytemplate" then
insideAnotherCandy = true break end parent = parent.Parent end
if not insideAnotherCandy then
local contactParts = State.getCandieContactParts(item) local part = contactParts[1]
if part and part.Parent then
table.insert(candidates, { item = item, part = part, parts = contactParts, }) end end end end
return candidates end
State.getCandieDropCFrame = function(part, root, tryIndex, character)
if not part or not part.Parent or not root or not character then
return nil end
local offsets = { Vector3.new(0, 0, 0), Vector3.new(0.85, 0, 0), Vector3.new(-0.85, 0, 0),
Vector3.new(0, 0, 0.85), Vector3.new(0, 0, -0.85), }
local index = (math.max(1, math.floor(tryIndex or 1)) - 1) % #offsets + 1
local point = part.Position + offsets[index] local params = RaycastParams.new()
params.FilterType = Enum.RaycastFilterType.Exclude local ignored = { character }
local target = part
while target.Parent and string.lower(target.Name) ~= "candytemplate" do
target = target.Parent end table.insert(ignored, target)
params.FilterDescendantsInstances = ignored params.IgnoreWater = true
params.RespectCanCollide = true
local hit = workspace:Raycast(point + Vector3.new(0, 4.5, 0), Vector3.new(0, -25, 0), params)
if not hit or hit.Normal.Y < 0.6 or hit.Material == Enum.Material.Water then
return nil end local floorY = hit.Position.Y
if floorY > part.Position.Y + 1.65 or part.Position.Y - floorY > 5.0 then
return nil end local destinationY = math.max(floorY + 2.65, part.Position.Y + 1.7)
if destinationY - floorY > 5.0 then
return nil end
return CFrame.new(point.X, destinationY, point.Z) * root.CFrame.Rotation end
State.isCandieWithinReach = function(root, part)
if not root or not part or not part.Parent then
return false end local nearest = part.CFrame:PointToObjectSpace(root.Position)
local extent = part.Size * 0.5
local excess = Vector3.new(math.max(0, math.abs(nearest.X) - extent.X),
math.max(0, math.abs(nearest.Y) - extent.Y), math.max(0, math.abs(nearest.Z) - extent.Z))
return excess.Magnitude <= 4.25 end
State.isCandiePathBlocked = function(character, root, part)
if not character or not root or not part or not part.Parent then
return false end local delta = part.Position - root.Position if delta.Magnitude < 0.5 then
return false end local rayParams = RaycastParams.new()
rayParams.FilterType = Enum.RaycastFilterType.Exclude
rayParams.FilterDescendantsInstances = { character } rayParams.RespectCanCollide = true
local hit = workspace:Raycast(root.Position, delta, rayParams)
return hit ~= nil and hit.Instance ~= part and hit.Distance < delta.Magnitude - 0.3 end
