State.buildCandieScanRoute = function(candyFolder)
local names = { "abobora", "picole sinistro", "muro com cerca", "lapide", }
local byName = {} local groups = {} for order, name in ipairs(names) do
byName[normalizeCandieWaypointName(name)] = order groups[order] = {} end
for _, item in ipairs(workspace:GetDescendants()) do
if (item:IsA("Model") or item:IsA("BasePart")) and item.Parent
and (not candyFolder or not item:IsDescendantOf(candyFolder))
and (not player.Character or not item:IsDescendantOf(player.Character)) then
local normalized = normalizeCandieWaypointName(item.Name)
local groupIndex = byName[normalized] if groupIndex then
local parent = item.Parent local nestedDuplicate = false
while parent and parent ~= workspace do
if parent:IsA("Model") and normalizeCandieWaypointName(parent.Name) == normalized then
nestedDuplicate = true break end parent = parent.Parent end if not nestedDuplicate then
local ok, position = pcall(function() if item:IsA("BasePart") then
return item.Position end if not item:FindFirstChildWhichIsA("BasePart", true) then
return nil end return item:GetPivot().Position end) if ok and position then
table.insert(groups[groupIndex], { Name = names[groupIndex], Target = item,
Position = position, }) end end end end end local route = {}
for _, group in ipairs(groups) do
table.sort(group, function(a, b) if a.Position.X ~= b.Position.X then
return a.Position.X < b.Position.X end if a.Position.Z ~= b.Position.Z then
return a.Position.Z < b.Position.Z end if a.Position.Y ~= b.Position.Y then
return a.Position.Y < b.Position.Y end
return a.Target:GetFullName() < b.Target:GetFullName() end)
for _, entry in ipairs(group) do
table.insert(route, entry) end end return route end
State.getCandieScanCFrame = function(character, root, candyFolder, waypoint)
