local sideZ = math.clamp(boxSize.Z * 0.5 + 6, 8, 24)
local places = { Vector3.new(0, 0, sideZ), Vector3.new(sideX, 0, 0), Vector3.new(0, 0, -sideZ),
Vector3.new(-sideX, 0, 0), } local bottomY = boxCFrame.Position.Y - boxSize.Y * 0.5
