return feature.ServerMarkers or {}, feature.SyncWorking == true end
State.candyLandingAtMarker = function(character, humanoid, root, folder, position)
local params = RaycastParams.new() params.FilterType = Enum.RaycastFilterType.Exclude
params.FilterDescendantsInstances = folder and {character, folder} or {character}
params.RespectCanCollide = true params.IgnoreWater = true
local offsets = { Vector3.zero, Vector3.new(1.15, 0, 0), Vector3.new(-1.15, 0, 0),
Vector3.new(0, 0, 1.15), Vector3.new(0, 0, -1.15), }
local height = math.max(2.65, root.Size.Y * 0.5 + humanoid.HipHeight + 0.3)
for _, offset in ipairs(offsets) do
local sample = position + offset for _, startHeight in ipairs({3.8, 10}) do
local hit = workspace:Raycast(sample + Vector3.new(0, startHeight, 0), Vector3.new(0, -48, 0), params)
if hit and hit.Normal.Y >= 0.62 and hit.Material ~= Enum.Material.Water
and hit.Position.Y <= position.Y + 1.5 and position.Y - hit.Position.Y <= 6 then
local y = math.max(hit.Position.Y + height, position.Y + 2.8) if y <= position.Y + 6 then
return CFrame.new(sample.X, y, sample.Z) * root.CFrame.Rotation end end end end
return nil end
State.candyScanWaypointCFrame = function(character, humanoid, root, folder, point)
local params = RaycastParams.new() params.FilterType = Enum.RaycastFilterType.Exclude
params.FilterDescendantsInstances = folder and { character, folder } or { character }
params.IgnoreWater = true params.RespectCanCollide = true
local hit = workspace:Raycast(point + Vector3.new(0, 7.5, 0), Vector3.new(0, -28, 0), params)
if not hit or hit.Normal.Y < 0.62 or hit.Material == Enum.Material.Water
or math.abs(hit.Position.Y - point.Y) > 8.5 or hit.Position.Y > point.Y + 0.6 then
return nil end local height = math.max(2.65, humanoid.HipHeight + root.Size.Y * 0.5 + 0.3)
local rootY = math.max(point.Y, hit.Position.Y + height)
if rootY - hit.Position.Y > 6.5 then
return nil end return CFrame.new(point.X, rootY, point.Z) * root.CFrame.Rotation end
