local function isGameGui(screen)
return screen and screen:IsA("ScreenGui") and not hubOwned(screen)
and screen.Name ~= "CoinClickerGui" end
local function releaseScreen(screen)
local record = uiGuard.Hidden[screen]
if not record then return end
uiGuard.Hidden[screen] = nil
if record.Connection then record.Connection:Disconnect() end
if screen and screen.Parent then
pcall(function() screen.Enabled = record.WasEnabled end) end end
local function hideScreen(screen)
if not isGameGui(screen) or uiGuard.Hidden[screen] then return end
local record = {WasEnabled = screen.Enabled}
uiGuard.Hidden[screen] = record
record.Connection = screen:GetPropertyChangedSignal("Enabled"):Connect(function()
if uiGuard.Active and not uiGuard.Stopped and screen.Parent and screen.Enabled then
screen.Enabled = false end end)
if screen.Enabled then screen.Enabled = false end end
local function sync()
if uiGuard.Stopped then return end
local shouldHide = State.Running and State.coinClickerNoNativeMenu()
and State.isCoinClickerLaptopEquipped()
if shouldHide then
uiGuard.Active = true
for _, child in ipairs(playerGui:GetChildren()) do hideScreen(child) end
else
uiGuard.Active = false
for screen in pairs(uiGuard.Hidden) do releaseScreen(screen) end
end
if State.refreshCoinClickerNativeMenuGuard then
pcall(State.refreshCoinClickerNativeMenuGuard) end
end
State.refreshCoinClickerEquippedUIs = sync
local function clearCharacterConnections()
