table.clear(uiGuard.CharacterConnections) end
local function watchCharacter(character)
clearCharacterConnections()
if character then
local function later() task.defer(sync) end
table.insert(uiGuard.CharacterConnections, character.ChildAdded:Connect(later))
table.insert(uiGuard.CharacterConnections, character.ChildRemoved:Connect(later))
