env.__UnicornHubRestoreEquippedUIs = nil end end end)
end
_G.__UnicornHubRestoreEquippedUIs = uiGuard.Stop
pcall(function() if type(getgenv) == "function" then
local env = getgenv()
if type(env) == "table" then env.__UnicornHubRestoreEquippedUIs = uiGuard.Stop end end end)
watchCharacter(player.Character)
task.spawn(function()
