State.potionFindProtocol = function(feature)
local features = ReplicatedStorage:FindFirstChild("Features")
if not features then return false end
local candidates = {"WerewolfPotions", "WerewolfPotion", "HalloweenPotions", "PotionCollectibles", "Potions"}
for _, name in ipairs(candidates) do
local group = features:FindFirstChild(name)
local remotes = group and group:FindFirstChild("Remotes")
local sync = remotes and remotes:FindFirstChild("Sync")
local pickup = remotes and remotes:FindFirstChild("Pickup")
if sync and sync:IsA("RemoteFunction") and pickup and pickup:IsA("RemoteFunction") then
feature.SyncRemote, feature.PickupRemote = sync, pickup if not feature.PickupRadius then
local configScript = group:FindFirstChild("Config")
if configScript and configScript:IsA("ModuleScript") then
local ok, config = pcall(require, configScript)
if ok and type(config) == "table" and type(config.PickupRadius) == "number" then
feature.PickupRadius = config.PickupRadius end end end return true end end
feature.SyncRemote, feature.PickupRemote = nil, nil return false end
State.potionCountOnce = function(feature, identity, estimated)
if not identity or feature.Counted[identity] then return false end
feature.Counted[identity] = true feature.Collected = (feature.Collected or 0) + 1
feature.LastStatus = (estimated and "Pocao removida (coleta estimada): " or "Pocao coletada: ")
.. tostring(feature.Collected)
if feature.CurrentTarget == identity then feature.CurrentTarget = nil end return true end
