State.fetchAdminPanelUsers = function(force)
    if not State.Plus.IsOwner or not State.getAdminPanelKey() then return false end
    local api = State.AdminPresenceApi
    local at = os.clock()
    if api.UsersBusy then return false end
    if force ~= true and at - (api.LastUsersAttempt or -math.huge) < 7 then
        return api.LastUsersFetch > 0
    end
    api.LastUsersAttempt = at
    api.UsersBusy = true
    local callOk, ok, data = pcall(State.adminPanelRequest, "GET", "/v1/users", nil, true)
    api.UsersBusy = false
    if not callOk or not ok or type(data.users) ~= "table" then return false end
    local lastSeen = os.clock()
    for _, info in ipairs(data.users) do
        local uid = tonumber(info.userId)
        if uid and uid > 0 then
            local key = tostring(math.floor(uid))
            local old = State.Admin.HubUsers[key]
            State.Admin.HubUsers[key] = {
                FirstSeen = old and old.FirstSeen or lastSeen,
                LastSeen = lastSeen,
                AllowAdmin = info.allowAdmin == true,
                Plus = info.plus == true,
                PlaceId = tonumber(info.placeId),
                JobId = tostring(info.jobId or ""),
                Username = tostring(info.username or ""):sub(1, 60),
                DisplayName = tostring(info.displayName or ""):sub(1, 60),
                ClientVersion = old and old.ClientVersion or 0,
            }
        end
    end
    api.LastUsersFetch = lastSeen
    return true
end
State.adminPresenceHeartbeat = function()
    local api = State.AdminPresenceApi
    local payload = {
        userId = player.UserId,
        username = tostring(player.Name),
        displayName = tostring(player.DisplayName),
        plus = State.Plus.IsOwner or State.Plus.Enabled == true,
        placeId = game.PlaceId,
        jobId = tostring(game.JobId or ""),
        -- Only the client's existing authorization is transmitted.
        allowAdmin = not State.Plus.IsOwner and State.Admin.AllowOwnerAdmin == true,
        session = api.Session,
    }
    local ok, data = State.adminPanelRequest("POST", "/v1/heartbeat", payload, false)
    if not ok then return false end
    if type(data.session) == "string" and data.session ~= "" then
        api.Session = data.session
    end
    return true
end
-- The recipient polls only its own session and applies commands only while
-- the preexisting opt-in is active. It also verifies the owner's Roblox UserId.
State.pollAdminPanelCommand = function()
    local api = State.AdminPresenceApi
    if State.Plus.IsOwner or not api.Session or not State.Admin.AllowOwnerAdmin then
        return false
    end
    local ok, data = State.adminPanelRequest("POST", "/v1/poll", {
        userId = player.UserId, session = api.Session,
    }, false)
    if not ok then
        if data and data.error == "SESSION_REQUIRED" then
            api.Session = nil
            -- Recover a lost in-memory Render session without waiting 25 seconds.
            task.spawn(function() pcall(State.adminPresenceHeartbeat) end)
        end
        return false
    end
    local cmd = data.command
    if type(cmd) ~= "table" then return true end
    local nonce = tostring(cmd.nonce or "")
    local action = tostring(cmd.action or ""):lower()
    if nonce == "" or nonce == api.LastCommandNonce then return true end
    api.LastCommandNonce = nonce
    local allowed = State.HubAdminApi.ActionToCode[action] ~= nil
        and tonumber(cmd.ownerUserId) == tonumber(State.Plus.OwnerUserId)
        and Players:GetPlayerByUserId(State.Plus.OwnerUserId) ~= nil
        and State.Admin.AllowOwnerAdmin == true
    local applied, result = false, "CONSENT_OR_OWNER_MISMATCH"
    if allowed then
        local callOk, success, reason = pcall(State.applyConsentedAdminCommand, action, false)
        applied = callOk and success == true
        result = callOk and tostring(reason or "NO_RESULT") or "CLIENT_ERROR"
    end
    State.adminPanelRequest("POST", "/v1/ack", {
        userId = player.UserId,
        session = api.Session,
        nonce = nonce,
        ok = applied,
        result = result,
    }, false)
    return applied
end
State.startAdminPresence = function()
    local api = State.AdminPresenceApi
    if api.Running then return end
    api.Running = true
    api.Token += 1
    local token = api.Token
    task.spawn(function()
        while State.Running and api.Running and token == api.Token do
            local requestOk, heartbeatOk = pcall(State.adminPresenceHeartbeat)
            if not requestOk or heartbeatOk ~= true then
                if not requestOk then api.LastError = "HEARTBEAT_ERROR" end
                local at = os.clock()
                if at - (api.LastWarnAt or -math.huge) > 30 then
                    api.LastWarnAt = at
                    warn("[Unicorn Hub] Presenca Render indisponivel:", tostring(api.LastError or "REQUEST_FAILED"))
                end
            end
            if State.Plus.IsOwner then
                task.spawn(function() pcall(State.fetchAdminPanelUsers) end)
            end
            local elapsed = 0
            local heartbeatInterval = (requestOk and heartbeatOk == true) and 25 or 6
            while elapsed < heartbeatInterval and State.Running and api.Running and token == api.Token do
                task.wait(1)
                elapsed += 1
            end
        end
        if token == api.Token then api.Running = false end
    end)
    -- A separate light polling worker prevents the heartbeat's 25s cadence
    -- from delaying remotely authorized commands.
    if not State.Plus.IsOwner then
        task.spawn(function()
            task.wait(1.0)
            while State.Running and api.Running and token == api.Token do
                if State.Admin.AllowOwnerAdmin == true then
                    local ok, err = pcall(State.pollAdminPanelCommand)
                    if not ok then
                        local at = os.clock()
                        if at - (api.LastPollWarnAt or -math.huge) > 20 then
                            api.LastPollWarnAt = at
                            warn("[Unicorn Hub] Falha no polling ADM:", tostring(err))
                        end
                    end
                end
                local interval = isMobile and 2.0 or 1.45
                local waited = 0
                while waited < interval and State.Running and api.Running and token == api.Token do
                    task.wait(0.25)
                    waited += 0.25
                end
            end
        end)
    end
end
