State.startRemoteBridge = function()
    local bridge = State.RemoteBridge
    if bridge.Running or bridge.Url == "" then return end
    bridge.Running = true
    bridge.Token += 1
    local generation = bridge.Token
    task.spawn(function()
        while State.Running and bridge.Running and generation == bridge.Token do
            local success = false
            local pollDelay = 4.5
            if not bridge.Session then
                local ok, data = State.remoteBridgeRequest("/v1/connect", {
                    userId = player.UserId, username = tostring(player.Name),
                    displayName = tostring(player.DisplayName),
                    plus = State.Plus.IsOwner or State.Plus.Enabled == true,
                    placeId = game.PlaceId, jobId = tostring(game.JobId or ""),
                })
                if ok and type(data.session) == "string" then
                    bridge.Session = data.session
                    success = true
                end
            else
                local ok, data = State.remoteBridgeRequest("/v1/poll", {
                    userId = player.UserId, session = bridge.Session,
                })
                if ok then
                    success = true
                    if type(data.config) == "table" then bridge.Config = data.config end
                    local command = data.command
                    if type(command) == "table" and type(command.id) == "string" then
                        local commandId = command.id
                        if bridge.LastCommandId ~= commandId then
                            bridge.LastCommandId = commandId
                            local action = tostring(command.action or "")
                            bridge.LastCommandOk = action == "ping" or action == "notice" or action == "refresh_config"
                            bridge.LastCommandResult = bridge.LastCommandOk and "OK" or "UNSUPPORTED_ACTION"
                            if action == "notice" then
                                warn("[Unicorn Hub] Aviso remoto: " .. tostring(command.message or ""):sub(1,180))
                            end
                        end
                        local ackOk = State.remoteBridgeRequest("/v1/ack", {
                            userId = player.UserId, session = bridge.Session,
                            commandId = commandId, ok = bridge.LastCommandOk,
                            result = bridge.LastCommandResult,
                        })
                        if ackOk then bridge.LastCommandId = commandId end
                    end
                end
            end
            if not success then pollDelay = 12 end
            local elapsed = 0
            while elapsed < pollDelay and State.Running and bridge.Running and generation == bridge.Token do
                task.wait(0.5)
                elapsed += 0.5
            end
        end
        if generation == bridge.Token then bridge.Running = false end
    end)
end
