return false end if not State.fetchApiPresence() then
return false end local ownerId = tonumber(State.Plus.OwnerUserId)
local commandTarget, commandAction, commandNonce = nil, nil, nil
for _, info in ipairs(State.Api.PresenceUsers or {}) do
if tonumber(info.userId) == ownerId then
local candidates = { tostring(info.username or ""), tostring(info.displayName or ""), }
for _, raw in ipairs(candidates) do
local targetText, actionCode, nonceText = string.match(raw, "^|[CQ]=(%d+),([bfusr]),([%w]+)$")
if targetText then
commandTarget = tonumber(targetText)
commandAction = State.HubAdminApi.CodeToAction[ tostring(actionCode or "") ]
commandNonce = tostring(nonceText or "") break end end break end end
if commandTarget ~= player.UserId or type(commandAction) ~= "string" or commandAction == ""
or type(commandNonce) ~= "string" or commandNonce == "" then
return false end
if State.Api.LastInboundCommand == commandNonce or State.Api.InboundPromptNonce == commandNonce then
return false end State.Api.InboundPromptNonce = commandNonce
local function finishRequest(accepted)
if State.Api.LastInboundCommand == commandNonce then
return end State.Api.InboundPromptNonce = nil State.Api.LastInboundCommand = commandNonce
local applied = false local result = "CONSENT_DENIED" if accepted == true then
applied, result = State.applyConsentedAdminCommand(commandAction, true) end
State.Api.LastCommandAck = { Id = commandNonce, Action = commandAction, Ok = applied == true,
Result = tostring(result or ""), At = os.clock(), }
State.Api.OutboundAck = { Nonce = commandNonce, Ok = applied == true, ExpiresAt = os.clock()
+ (tonumber(State.HubAdminApi.AckTTL) or 10), } State.apiHeartbeat() end
if State.Admin.AllowOwnerAdmin == true then
finishRequest(true)
else
finishRequest(false) end
return true, "REQUEST_RECEIVED" end State.sendAdminCommand = function(userId, action)
    if not State.Plus.IsOwner then return false, "OWNER_ONLY" end
    userId = tonumber(userId)
    if not userId or userId <= 0 then return false, "INVALID_ID" end
    userId = math.floor(userId)
    action = string.lower(tostring(action or ""))
    if not State.HubAdminApi.ActionToCode[action] then return false, "INVALID_COMMAND" end
    if not State.getAdminPanelKey() then return false, "ADMIN_KEY_REQUIRED" end
    local entry = State.Admin.HubUsers[tostring(userId)]
    if not entry then
        pcall(State.fetchAdminPanelUsers, true)
        entry = State.Admin.HubUsers[tostring(userId)]
    end
    if entry then
        if entry.AllowAdmin ~= true then return false, "CONSENT_REQUIRED" end
        if tonumber(entry.PlaceId) ~= tonumber(game.PlaceId)
            or tostring(entry.JobId or "") ~= tostring(game.JobId or "") then
            return false, "OTHER_SERVER"
        end
    end
    local ok, response = State.adminPanelRequest("POST", "/v1/command", {
        targetUserId = userId, action = action,
    }, true)
    if not ok then
        return false, tostring(response and response.error or "API_ERROR")
    end
    local nonce = tostring(response.nonce or "")
    if nonce == "" then return false, "INVALID_RESPONSE" end
    local deadline = os.clock() + 12.0
    local lastError = nil
    while State.Running and os.clock() < deadline do
        task.wait(0.85)
        local statusOk, statusData = State.adminPanelRequest("GET",
            "/v1/status?nonce=" .. HttpService:UrlEncode(nonce), nil, true)
        if statusOk and type(statusData) == "table" then
            local status = tostring(statusData.status or "")
            if status == "applied" then return true, "APPLIED" end
            if status == "denied" then
                return false, tostring(statusData.result or "TARGET_DENIED_OR_FAILED")
            end
            if status == "expired" then return false, "NO_ACK" end
        elseif type(statusData) == "table" then
            lastError = tostring(statusData.error or "API_ERROR")
        end
    end
    return false, lastError or "NO_ACK"
end
