State.makePersistentOptionKey = function(titleText, suffix)
local normalized = string.lower(tostring(titleText or "option" ))
normalized = string.gsub(normalized, "[^%w]+", "_" )
normalized = string.gsub(normalized, "^_+", "" )
normalized = string.gsub(normalized, "_+$", "" ) if normalized == "" then
normalized = "option" end local key = "UIOption_" .. normalized
if suffix and suffix ~= "" then
key ..= "_" .. tostring(suffix) end return key end
State.getPersistentOption = function(titleText, suffix)
return getCachedSetting(State.makePersistentOptionKey(titleText, suffix)) end
State.savePersistentOption = function(titleText, value, suffix)
saveSetting(State.makePersistentOptionKey(titleText, suffix), value) end
