State.tagStudioSelectEffect = function(profile, effectId, userId)
effectId = State.tagStudioEffectId(effectId)
local data = State.TagStudio.EffectInfo[effectId]
if data and data.OwnerOnly and tonumber(userId) ~= State.Plus.OwnerUserId then
return false end profile.TagEffect = effectId if data then
if data.Fixed then profile.Tag = data.Fixed end
if data.Cor1 then profile.Cor1Tag = State.tagStudioHex(data.Cor1) end
if data.Cor2 then profile.Cor2Tag = State.tagStudioHex(data.Cor2) end
if data.TagFont then profile.TagFont = data.TagFont end end return true end
State.tagStudioColor = function(value, fallback) local r, g, b
local raw = string.gsub(tostring(value or ""), "%s", "")
if string.match(raw, "^#?%x%x%x%x%x%x$") then
raw = string.gsub(raw, "^#", "") r = tonumber(string.sub(raw, 1, 2), 16)
g = tonumber(string.sub(raw, 3, 4), 16) b = tonumber(string.sub(raw, 5, 6), 16)
else
local a, bb, c = string.match(raw, "^(%d+),(%d+),(%d+)$")
r, g, b = tonumber(a), tonumber(bb), tonumber(c) end
if not r or not g or not b or r > 255 or g > 255 or b > 255 then
return fallback or Color3.fromRGB(160, 255, 50), false end
return Color3.fromRGB(r, g, b), true end State.tagStudioHex = function(value)
local c = State.tagStudioColor(value, Color3.fromRGB(160, 255, 50))
return string.format("#%02X%02X%02X", math.floor(c.R * 255 + 0.5),
math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5)) end
