local raw = State.getPersistentOption("Tag Studio", "Profile_" .. id)
if type(raw) == "string" and raw ~= "" then
local ok, profile = pcall(HttpService.JSONDecode, HttpService, raw)
if ok and type(profile) == "table" then
draft = {Profile = profile, Reset = false} end
else
draft = {Profile = nil, Reset = true} end end if draft then
drafts[#drafts + 1] = {Id = id, Draft = draft} end end for _, item in ipairs(drafts) do
State.queueTagRemoteWrite(item.Id, item.Draft.Profile, item.Draft.Reset) end
return #drafts end State.queueTagRemoteWrite = function(userId, profile, reset)
local ts = State.TagStudio local id = tostring(userId)
local draft = {Profile = profile, Reset = reset == true} ts.PendingDrafts[id] = draft
ts.UnpublishedProfiles[id] = draft State.persistTagStudioPending(id, true)
if not reset then
ts.RemoteProfiles[id] = profile  
else
ts.RemoteProfiles[id] = nil end if type(ts.WriteKey) ~= "string" or #ts.WriteKey < 12 then
ts.LastWriteError = "CHAVE_TAG_NAO_INFORMADA" ts.SyncStatus = "pendente_chave"
if type(ts.UpdateSyncLabel) == "function" then pcall(ts.UpdateSyncLabel) end return  
end ts.PendingWrites[id] = true ts.LastWriteError = nil ts.SyncStatus = "enviando"
if type(ts.UpdateSyncLabel) == "function" then pcall(ts.UpdateSyncLabel) end
if ts.Writing[id] then return end ts.Writing[id] = true task.spawn(function()
task.wait(0.22) while State.Running and ts.PendingDrafts[id] do
local draft = ts.PendingDrafts[id] ts.PendingDrafts[id] = nil
local methodPath = draft.Reset and "/tags/reset" or "/tags"
local payload = draft.Reset and {userId = id} or {userId = id, profile = draft.Profile}
local ok, result = State.tagStudioApiRequest("POST", methodPath, payload, true) if ok then
ts.LastWriteError = nil if not ts.PendingDrafts[id] then
ts.SyncStatus = "sincronizado" if draft.Reset then
ts.RemoteProfiles[id] = nil ts.RemoteRevisions[id] = nil
else
ts.RemoteProfiles[id] = result.profile or draft.Profile
ts.RemoteRevisions[id] = tostring(result.revision or "") end
ts.UnpublishedProfiles[id] = nil State.persistTagStudioPending(id, false)
ts.Revisions[id] = (ts.Revisions[id] or 0) + 1
if State.refreshUnicornHubTags then pcall(State.refreshUnicornHubTags) end end
else
ts.SyncStatus = "falha"
ts.LastWriteError = tostring((result and result.error) or "SERVER_UNAVAILABLE")
if not ts.PendingDrafts[id] then
ts.UnpublishedProfiles[id] = draft end
warn("[Unicorn Hub V118] Tag so local, publicacao pendente: " .. tostring(ts.LastWriteError)) end
if type(ts.UpdateSyncLabel) == "function" then pcall(ts.UpdateSyncLabel) end
if ts.PendingDrafts[id] then task.wait(0.10) end end ts.Writing[id] = nil
ts.PendingWrites[id] = nil
if type(ts.UpdateSyncLabel) == "function" then pcall(ts.UpdateSyncLabel) end end) end
State.fetchRemoteTagProfiles = function(ids) local ts = State.TagStudio
if not State.Running or ts.RemoteBusy then return false end
local queryIds, unique = {}, {} for _, id in ipairs(ids) do
local number = tonumber(id)
if number and number > 0 and number % 1 == 0 and #queryIds < 100 then
local key = tostring(number) if not unique[key] then
unique[key] = true queryIds[#queryIds + 1] = key end end end
if #queryIds == 0 then return false end ts.RemoteBusy = true
ts.LastRemoteAttempt = os.clock()
local ok, result = State.tagStudioApiRequest( "GET", "/tags?ids=" .. table.concat(queryIds, ","), nil, false)
ts.RemoteBusy = false if not ok then
ts.LastSyncError = tostring(result and result.error or "SERVER_UNAVAILABLE")
if ts.SyncStatus ~= "enviando" then ts.SyncStatus = "indisponivel" end
if type(ts.UpdateSyncLabel) == "function" then pcall(ts.UpdateSyncLabel) end
return false end ts.LastRemotePoll = os.clock() ts.LastSyncError = nil
if ts.SyncStatus ~= "enviando" and ts.SyncStatus ~= "falha" and ts.SyncStatus ~= "pendente_chave" then
ts.SyncStatus = "conectado" end
local profiles = type(result.profiles) == "table" and result.profiles or {}
local changed = false for _, id in ipairs(queryIds) do
if not ts.PendingWrites[id] and not ts.UnpublishedProfiles[id] and not ts.PendingIds[id] then
local entry = profiles[id]
local newProfile = type(entry) == "table" and entry.profile or nil
local revision = newProfile and tostring(entry.revision or "") or nil
local oldRevision = ts.RemoteRevisions[id]
local previouslyRemote = ts.RemoteProfiles[id] ~= nil
if revision ~= oldRevision or previouslyRemote ~= (newProfile ~= nil) then
ts.RemoteProfiles[id] = newProfile ts.RemoteRevisions[id] = revision
ts.Revisions[id] = (ts.Revisions[id] or 0) + 1 changed = true end end end
if changed and State.refreshUnicornHubTags then pcall(State.refreshUnicornHubTags) end
if type(ts.UpdateSyncLabel) == "function" then pcall(ts.UpdateSyncLabel) end
return true end State.saveTagStudioConfig = function(userId, profile)
local id = tostring(userId)
local resolvedEffect = State.tagStudioEffectId(profile.TagEffect)
local effectInfo = State.TagStudio.EffectInfo[resolvedEffect]
if effectInfo and effectInfo.OwnerOnly and tonumber(id) ~= State.Plus.OwnerUserId then
resolvedEffect = "default" end local validFont = false
for _, font in ipairs(State.TagStudio.Fonts) do
if font == profile.TagFont then
validFont = true break end end
local cleaned = { Tag = string.sub(tostring(profile.Tag or "Lie"), 1, 24),
Active = profile.Active ~= false, TagEffect = resolvedEffect,
TagFont = validFont and profile.TagFont or "GothamBold",
Cor1Tag = State.tagStudioHex(profile.Cor1Tag), Cor2Tag = State.tagStudioHex(profile.Cor2Tag), }
if cleaned.Tag == "" then cleaned.Tag = "Lie" end if resolvedEffect == "lie" then
local preset = State.TagStudio.EffectInfo.lie cleaned.Tag = preset.Fixed
cleaned.TagFont = preset.TagFont cleaned.Cor1Tag = State.tagStudioHex(preset.Cor1)
cleaned.Cor2Tag = State.tagStudioHex(preset.Cor2) end State.TagStudio.Cache[id] = cleaned
if State.Plus.IsOwner then
State.TagStudio.RemoteProfiles[id] = cleaned end
State.TagStudio.Revisions[id] = (State.TagStudio.Revisions[id] or 0) + 1
State.savePersistentOption("Tag Studio", HttpService:JSONEncode(cleaned), "Profile_" .. id)
if State.flushPersistentCache then State.flushPersistentCache() end
if tonumber(id) == player.UserId then
if State.UnicornHubTagEnabled ~= cleaned.Active then
State.TagStudio.SuppressTogglePush = true State.setUnicornHubTagEnabled(cleaned.Active)
State.TagStudio.SuppressTogglePush = false end end
if State.Plus.IsOwner and State.queueTagRemoteWrite then
State.queueTagRemoteWrite(id, cleaned, false) end
if State.refreshUnicornHubTags then State.refreshUnicornHubTags() end
if State.UnicornHubTagRuntime and State.UnicornHubTagRuntime.RefreshSettingsSwitch then
State.UnicornHubTagRuntime.RefreshSettingsSwitch(false) end return cleaned end
State.resetTagStudioConfig = function(userId) local id = tostring(userId)
State.TagStudio.Cache[id] = false
State.TagStudio.Revisions[id] = (State.TagStudio.Revisions[id] or 0) + 1
State.savePersistentOption("Tag Studio", "", "Profile_" .. id)
if State.flushPersistentCache then State.flushPersistentCache() end
State.TagStudio.RemoteProfiles[id] = nil State.TagStudio.RemoteRevisions[id] = nil
if State.Plus.IsOwner and State.queueTagRemoteWrite then
State.queueTagRemoteWrite(id, nil, true) end
if State.refreshUnicornHubTags then State.refreshUnicornHubTags() end
if State.UnicornHubTagRuntime and State.UnicornHubTagRuntime.RefreshSettingsSwitch then
State.UnicornHubTagRuntime.RefreshSettingsSwitch(false) end end
State.resolveTagStudioFont = function(fontName)
local name = tostring(fontName or "GothamBold")
local aliases = {Arimo = "Arial", ArimoBold = "ArialBold", Roboto = "Gotham",
RobotoCondensed = "Gotham", Ubuntu = "Gotham", Nunito = "Gotham",
Sarpanch = "Gotham", BuilderSans = "Gotham", BuilderSansMedium = "GothamMedium",
BuilderSansBold = "GothamBold", BuilderSansExtraBold = "GothamBlack",
RobotoMono = "Code", Jura = "Code", Michroma = "SciFi",
Bodoni = "Garamond", Merriweather = "Garamond", Oswald = "GothamBold",
SpecialElite = "Antique", AmaticSC = "Cartoon", Bangers = "Cartoon",
Creepster = "Fantasy", DenkOne = "GothamBold", Fondamento = "Garamond",
FredokaOne = "Cartoon", GrenzeGotisch = "Fantasy", IndieFlower = "Cartoon",
JosefinSans = "Gotham", Kalam = "Cartoon", LuckiestGuy = "Cartoon",
