State.createTagStudioEffect = function(kind, studio, container, label, gradient, gui, userId)
kind = State.tagStudioEffectId(kind)
if kind == "default" or kind == "lie" then return nil end
local data = State.TagStudio.EffectInfo[kind]
local c1 = State.tagStudioColor(studio and studio.Cor1Tag)
local c2 = State.tagStudioColor(studio and studio.Cor2Tag, Color3.fromRGB(255,255,255))
local moving = {} local ornaments = {}
local function glyph(symbol, x, y, size, color, font) local g = Instance.new("TextLabel")
g.Name = "Studio" .. kind g.AutoLocalize = false g.Size = UDim2.fromOffset(size, size)
g.AnchorPoint = Vector2.new(0.5, 0.5) g.Position = UDim2.fromScale(x, y)
g.BackgroundTransparency = 1 g.Text = symbol g.TextScaled = true
g.Font = font or Enum.Font.GothamBold g.TextColor3 = color
g.TextStrokeColor3 = Color3.fromRGB(9, 8, 18) g.TextStrokeTransparency = 0.55 g.ZIndex = 2
g.Parent = container return g end local symbolFor = {
angel="✦", demon="◆", devil="♨", crown="✦", void="●", blackhole="◉",
scramble="?", mystery="◇", ocean="≈", matrix="1", neon="✧", cyber="▣",
vampire="♦", toxic="☣", love="♥", sakura="❀", phoenix="✦",
celestial="✧", inferno="✦", frost="❄", phantom="◇", thunder="⚡",
absorbed="♦", singularity="◉", corrupted="#", seraph="✦", overlord="◆", eclipse="✧"
} local symbol = symbolFor[kind] local aura = data and (data.Type == "aura" or data.Aura)
local scale = nil if kind == "neon" or kind == "blackhole" or kind == "love" or aura then
scale = Instance.new("UIScale") scale.Name = "StudioTagPulse" scale.Scale = 1
scale.Parent = container end
if aura or kind == "eclipse" or kind == "blackhole" or kind == "void" then
local ring = Instance.new("Frame") ring.Name = "StudioAura"
ring.BackgroundTransparency = 1 ring.AnchorPoint = Vector2.new(0.5, 0.5)
ring.Position = UDim2.fromScale(0.5, 0.5) ring.Size = UDim2.new(1, -8, 1, -1)
ring.ZIndex = 1 ring.Parent = container local round = Instance.new("UICorner")
round.CornerRadius = UDim.new(1, 0) round.Parent = ring
local border = Instance.new("UIStroke") border.Thickness = aura and 2.0 or 1.4
border.Color = c1 border.Transparency = 0.43 border.Parent = ring
ornaments[#ornaments + 1] = border end if kind == "angel" or kind == "seraph" then
glyph("◁", 0.09, 0.53, 26, c2) glyph("▷", 0.91, 0.53, 26, c2)
glyph("◯", 0.50, -0.02, 22, c1) if kind == "seraph" then
glyph("❮", 0.01, 0.45, 24, c1) glyph("❯", 0.99, 0.45, 24, c1) end
elseif kind == "demon" or kind == "vampire" or kind == "overlord" then
glyph("▲", 0.24, 0.02, 16, c1) glyph("▲", 0.76, 0.02, 16, c2) if kind == "overlord" then
glyph("◆", 0.50, -0.09, 18, c2) end
elseif kind == "crown" then
glyph("♛", 0.50, -0.13, 27, c1)
elseif kind == "cyber" or kind == "glitch" or kind == "corrupted" then
local ghost = label:Clone() ghost.Name = "StudioGhost" ghost.TextColor3 = c2
ghost.TextTransparency = 0.58 ghost.TextStrokeTransparency = 0.8 ghost.ZIndex = 2
ghost.Parent = container ornaments[#ornaments + 1] = ghost
elseif kind == "eclipse" then
glyph("◉", 0.50, -0.08, 24, c2) end if symbol then
local count = (kind == "celestial" or kind == "sakura" or kind == "love" or aura) and 7 or 4
for i = 1, count do
local x = (i * 0.173 + 0.11) % 1 local y = (i * 0.29 + 0.13) % 1
local piece = glyph(symbol, x, y, 9 + i % 3 * 3, i % 2 == 0 and c2 or c1,
kind == "matrix" and Enum.Font.Code or nil) piece.TextTransparency = 0.18 + i % 3 * 0.12
moving[#moving + 1] = piece end end local seconds = 0 local accumulator = 0
local phase = (tonumber(userId) or 0) % 7 local originalText = label.Text local connection
local function stepTagEffect(dt)
if not gui.Parent or not label.Parent then
if connection then connection:Disconnect(); connection = nil end return end
seconds += math.min(dt, isMobile and 1 or 0.1) accumulator += dt
if accumulator < (isMobile and 0.80 or (State.Performance.LowEnd and 0.085 or 0.05)) then return end
accumulator = 0 local wave = (math.sin(seconds * 3.5 + phase) + 1) * 0.5
if scale then scale.Scale = 0.975 + wave * 0.065 end if kind == "rainbow" then
local h = (seconds * 0.15) % 1 gradient.Color = ColorSequence.new({
ColorSequenceKeypoint.new(0, Color3.fromHSV(h, 0.96, 1)),
ColorSequenceKeypoint.new(0.5, Color3.fromHSV((h + 0.34) % 1, 0.96, 1)),
ColorSequenceKeypoint.new(1, Color3.fromHSV((h + 0.69) % 1, 0.96, 1))})
elseif kind == "glitch" or kind == "corrupted" or kind == "cyber" then
local ghost = ornaments[1] if ghost and ghost:IsA("TextLabel") then
ghost.Position = UDim2.fromOffset(math.floor(math.sin(seconds*29)*3),
math.floor(math.cos(seconds*23)*2)) ghost.TextTransparency = 0.55 + wave*0.27 end
label.Rotation = math.sin(seconds*30)*0.85
elseif kind == "scramble" or kind == "mystery" or kind == "matrix" then
local chars = {"#", "?", "0", "1", "X", "◇"}
if wave > (kind == "scramble" and 0.52 or 0.91) then
local replaceAt = 1 + math.floor((seconds*7) % math.max(1, #originalText))
label.Text = string.sub(originalText, 1, replaceAt-1)
.. chars[1 + math.floor(seconds*13) % #chars]
.. string.sub(originalText, replaceAt+1)
else
label.Text = originalText end
elseif kind == "ocean" then
gradient.Rotation = math.sin(seconds*1.8)*18
elseif kind == "thunder" then
label.TextStrokeTransparency = math.sin(seconds*15)>0.75 and 0.02 or 0.37
elseif kind == "inferno" or kind == "phoenix" or kind == "demon" or kind == "overlord" then
label.TextStrokeColor3 = c1:Lerp(c2, wave)
elseif kind == "void" or kind == "blackhole" or kind == "singularity" or kind == "eclipse" then
gradient.Rotation = seconds*27 % 360
elseif kind == "frost" or kind == "phantom" then
label.TextTransparency = 0.02 + wave*0.12
elseif kind == "neon" then
label.TextStrokeTransparency = 0.08 + wave*0.36
elseif kind == "vampire" or kind == "absorbed" then
label.TextStrokeTransparency = 0.10 + wave*0.21 end for i, piece in ipairs(moving) do
local t = seconds*(kind == "thunder" and 2.8 or 0.75) + i*1.45
local x = (i*0.173 + math.sin(t)*0.045 + 0.11) % 1
local y = (i*0.29 + (kind == "sakura" and t*0.045 or -t*0.025) + 0.13) % 1
piece.Position = UDim2.fromScale(x,y) piece.Rotation = math.sin(t*1.8)*23
piece.TextTransparency = 0.18 + wave*0.40 end for _, item in ipairs(ornaments) do
if item:IsA("UIStroke") then item.Transparency = 0.36 + wave*0.37 end end end
if isMobile then
local active = true
connection = {Disconnect = function() active = false end}
task.spawn(function()
local previous = os.clock()
while active and State.Running and gui.Parent and label.Parent do
task.wait(0.8)
local now = os.clock()
if active and State.Running and gui.Parent and label.Parent then
stepTagEffect(now - previous)
end
previous = now
end
active = false
end)
else
connection = RunService.Heartbeat:Connect(stepTagEffect)
end
return connection end local function newUnicornHubTag(character, target, style)
