local NumberSuffixes = { [""] = 1, k = 1e3, m = 1e6, b = 1e9, t = 1e12, qa = 1e15, qi = 1e18, sx = 1e21,
sp = 1e24, oc = 1e27, no = 1e30, dc = 1e33, } local function parseNumber(text)
if not text or text == "" then
return 0 end local lower = string.lower(tostring(text))
lower = string.gsub(lower, ",", ".")
local value, suffix = string.match(lower, "(%d+%.?%d*)%s*(%a*)") if not value then
return 0 end local number = tonumber(value) or 0
local multiplier = NumberSuffixes[suffix or ""] or 1 return number * multiplier end
