local function isAllowedCoinGeneratorText(raw)
if type(raw) ~= "string" then return false end
local normalized = raw:gsub("(%l)(%u)", "%1 %2")
normalized = string.lower(normalized):gsub("[^%w]+", " ")
normalized = normalized:gsub("^%s+", ""):gsub("%s+$", "")
local padded = " " .. normalized .. " " if string.find(padded, " crystal ball ", 1, true)
or string.find(padded, " compass ", 1, true)
or string.find(padded, " photo booth ", 1, true) then
return true end return normalized == "crystalball" or normalized == "photobooth" end
