State.coinClickerHeadlessPurchases = function(now) local bg = State.CoinClickerBackground
local driver = bg and bg.Driver
if not (driver and bg.IsReady and State.Running and State.Plus.Enabled
and State.CoinClickerSilentEnabled and CoinClickerAutoEnabled) then
return false end
local autoGenerators = State.AutoItems or State.coinClickerFarmAutoGeneratorsEnabled()
if not (autoGenerators or State.AutoBuff) then
State.CoinClickerPurchaseStatus = "Compras automaticas desligadas" return false end
if now - bg.LastPurchaseAction < 0.35 then return false end
local pending = bg.PendingPurchase if pending then
local confirmed = false
if pending.Kind == "Generator" and type(driver.ownedAt) == "function" then
local ok, quantity = pcall(driver.ownedAt, pending.Index)
confirmed = ok and type(quantity) == "number" and quantity > pending.Before
elseif pending.Kind == "Upgrade" and type(driver.upgradePurchased) == "function" then
local ok, purchased = pcall(driver.upgradePurchased, pending.Id)
confirmed = ok and purchased == true end if confirmed then
if pending.Kind == "Generator" then
bg.ConfirmedGenerators += 1
else
bg.ConfirmedUpgrades += 1 end
State.CoinClickerPurchaseStatus = "Compra confirmada: " .. pending.Name
bg.PendingPurchase = nil bg.LastPurchaseAction = now
elseif now - pending.At >= 3 then
State.CoinClickerPurchaseStatus = "Compra nao confirmada: " .. pending.Name
bg.PendingPurchase = nil bg.LastPurchaseFailure = now bg.LastPurchaseAction = now end
return confirmed end if now - bg.LastPurchaseFailure < 2 then return false end
if not bg.Catalog or not bg.Upgrades then
local success = pcall(function() local coin = ReplicatedStorage:FindFirstChild("Features")
coin = coin and coin:FindFirstChild("CoinClicker") if not coin then return end
local catalogModule = coin:FindFirstChild("Catalog")
local upgradesModule = coin:FindFirstChild("Upgrades")
if catalogModule then bg.Catalog = require(catalogModule) end
if upgradesModule then bg.Upgrades = require(upgradesModule) end end) if not success then
State.CoinClickerPurchaseStatus = "Catalogo de compras indisponivel"
bg.LastPurchaseFailure = now return false end end local function matches(item, kind)
if kind == "Generator" then return isAllowedCoinGenerator(item) end
local choices = State.CoinClickerPurchaseChoices
local filter = choices and choices[kind] or ""
if type(filter) ~= "string" or filter == "" then return true end
filter = string.lower(filter)
local name = tostring(item.name or item.title or item.displayName
or item.label or item.id or "")
return string.find(string.lower(name), filter, 1, true) ~= nil end
local okBalance, balance = false, nil if type(driver.coins) == "function" then
okBalance, balance = pcall(driver.coins) end
if not okBalance or type(balance) ~= "number" then
State.CoinClickerPurchaseStatus = "Saldo indisponivel no motor" return false end
if autoGenerators and not bg.Catalog then
State.CoinClickerPurchaseStatus = "Catalogo de geradores indisponivel"
elseif autoGenerators and (type(driver.ownedAt) ~= "function"
or type(driver.priceAt) ~= "function") then
State.CoinClickerPurchaseStatus = "Motor sem dados de compra de geradores" end
if autoGenerators and bg.Catalog and type(driver.ownedAt) == "function"
and type(driver.priceAt) == "function" then
local list = bg.Catalog.generators or bg.Catalog.all if type(list) == "table" then
local bestIndex, bestGenerator, bestPrice = nil, nil, -1
for index, generator in ipairs(list) do
if type(generator) == "table" and matches(generator, "Generator") then
local ok, price = pcall(driver.priceAt, index)
if ok and type(price) == "number" and price > 0
and price <= balance and price > bestPrice then
bestIndex, bestGenerator, bestPrice = index, generator, price end end end
if bestIndex then
local method = bg.GeneratorBuyerName
if not method or type(driver[method]) ~= "function" then
for _, name in ipairs({"buyGenerator", "buyAt", "buyBuilding",
"purchaseGenerator"}) do
if type(driver[name]) == "function" then
method = name break end end end if method and type(driver[method]) == "function" then
local okCount, before = pcall(driver.ownedAt, bestIndex)
if okCount and type(before) == "number" then
local success, result = pcall(driver[method], bestIndex)
if success and result ~= false then
bg.GeneratorBuyerName = method
bg.PendingPurchase = {Kind = "Generator", Index = bestIndex,
Before = before, Name = tostring(bestGenerator.name or bestGenerator.id
or bestIndex), At = now} bg.LastPurchaseAction = now
State.CoinClickerPurchaseStatus = "Verificando gerador: " .. bg.PendingPurchase.Name
return true end end
else
State.CoinClickerPurchaseStatus = "Motor sem metodo de compra de gerador" end end end end
if State.AutoBuff and bg.Upgrades and type(bg.Upgrades.list) == "table"
and type(driver.buyUpgrade) == "function" then
for _, upgrade in ipairs(bg.Upgrades.list) do
if type(upgrade) == "table" and upgrade.id ~= nil and matches(upgrade, "Upgrade") then
local unlocked, purchased = true, false if type(driver.upgradeUnlocked) == "function" then
local ok, result = pcall(driver.upgradeUnlocked, upgrade.id)
unlocked = ok and result == true end if type(driver.upgradePurchased) == "function" then
local ok, result = pcall(driver.upgradePurchased, upgrade.id)
purchased = ok and result == true end local price = tonumber(upgrade.price)
if unlocked and not purchased and price and price > 0 and price <= balance then
local success, result = pcall(driver.buyUpgrade, upgrade)
if success and result ~= false then
bg.PendingPurchase = {Kind = "Upgrade", Id = upgrade.id,
Name = tostring(upgrade.name or upgrade.id), At = now} bg.LastPurchaseAction = now
State.CoinClickerPurchaseStatus = "Verificando upgrade: " .. bg.PendingPurchase.Name
return true end end end end end return false end
