local function setHiddenAncestorsVisible(button) local changed = {} local parent = button
while parent and parent ~= playerGui do
if parent:IsA("GuiObject") and not parent.Visible then
table.insert(changed, { object = parent, visible = parent.Visible, })
parent.Visible = true end parent = parent.Parent end return changed end
local function restoreHiddenAncestors(changed) for i = #changed, 1, -1 do
local item = changed[i] if item.object and item.object.Parent then
item.object.Visible = item.visible end end end local function getButtonCenter(button)
local size = button.AbsoluteSize local pos = button.AbsolutePosition
if size.X <= 2 or size.Y <= 2 then
return nil end local x = math.floor(pos.X + size.X * 0.5)
local y = math.floor(pos.Y + size.Y * 0.5) return x, y end
