State.getStaminaPercent = function(forceSearch) local runtime = State.CCAutoClick
local now = os.clock() local textObject = runtime.StaminaTextObject
if textObject and textObject.Parent and (textObject:IsA("TextLabel") or textObject:IsA("TextButton")) then
local cachedRaw = tostring(textObject.Text or "")
local percent = tonumber(string.match(cachedRaw, "(%d+%.?%d*)%s*%%" ))
if percent == nil then
percent = tonumber(string.match(cachedRaw, "(%d+%.?%d*)" )) end
if percent and percent >= 0 and percent <= 100 then
runtime.StaminaPercent = math.clamp(percent, 0, 100) runtime.LastStaminaRead = now
return runtime.StaminaPercent end
else
runtime.StaminaTextObject = nil end local bar = runtime.StaminaBarObject
if bar and bar.Parent and bar:IsA("GuiObject") and bar.Parent:IsA("GuiObject") then
local parentSize = bar.Parent.AbsoluteSize local barSize = bar.AbsoluteSize
local ratio = nil if parentSize.X > 4 and parentSize.X >= parentSize.Y then
ratio = barSize.X / parentSize.X
elseif parentSize.Y > 4 then
ratio = barSize.Y / parentSize.Y end if ratio and ratio >= 0 and ratio <= 1.05 then
runtime.StaminaPercent = math.clamp(ratio * 100, 0, 100) runtime.LastStaminaRead = now
return runtime.StaminaPercent end
else
runtime.StaminaBarObject = nil end local function readAttributes(instance)
if not instance then
return nil end local current = nil local maximum = nil
for key, value in pairs(instance:GetAttributes()) do
if type(value) == "number" then
local low = string.lower(tostring(key))
if string.find(low, "stamina", 1, true) or string.find(low, "energy", 1, true) then
if string.find(low, "max", 1, true) then
maximum = value
elseif string.find(low, "percent", 1, true) or string.find(low, "pct", 1, true) then
return math.clamp(value, 0, 100)
else
current = value end end end end if current ~= nil then
if maximum and maximum > 0 then
return math.clamp((current / maximum) * 100, 0, 100) end
if current >= 0 and current <= 100 then
return current end end return nil end local character = player.Character
local humanoid = character and character:FindFirstChildOfClass("Humanoid")
local attrPercent = readAttributes(player) or readAttributes(character) or readAttributes(humanoid)
if attrPercent ~= nil then
runtime.StaminaPercent = attrPercent runtime.LastStaminaRead = now return attrPercent end
if not forceSearch and now - runtime.LastStaminaSearch < 0.35 then
return runtime.StaminaPercent end runtime.LastStaminaSearch = now local roots = {}
local ccGui = getGui() if ccGui then
table.insert(roots, ccGui) end table.insert(roots, playerGui)
for _, root in ipairs(roots) do
local descendants = root:GetDescendants() for _, obj in ipairs(descendants) do
if (obj:IsA("TextLabel") or obj:IsA("TextButton")) and obj.Parent then
local raw = tostring(obj.Text or "")
local context = string.lower(tostring(obj.Name or "") .. " "
.. tostring(obj.Parent.Name or "") .. " " .. raw)
if string.find(context, "stamina", 1, true) or string.find(context, "energy", 1, true) then
