local centralClick = middle and button:IsDescendantOf(middle)
and (name == "click" or name == "clickbutton"
or name == "clickarea" or name == "clickzone")
if name == "coinclickbutton" or name == "coinclick" or name == "clickcoin"
or name == "clickerbutton" or name == "mainclickbutton"
or name == "rocoinclick" or name == "rocoinclickbutton"
or name == "cookiebutton" or name == "bigcookie"
or name == "maincookie" or centralClick then
runtime.Button = button return button end end end return nil   end
local cached = runtime.Button
if cached and cached.Parent and cached:IsA("GuiButton") and State.coinVisible(cached) then
return cached end local now = os.clock() if now - runtime.LastButtonSearch < 0.30 then
return nil end runtime.LastButtonSearch = now runtime.Button = nil runtime.Target = nil
local gui = getGui() if not gui then
return nil end local middle = getFrame("MiddleColumn") local root = middle or gui
local viewport = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(1280, 720)
local targetX = viewport.X * 0.50 local targetY = viewport.Y * 0.56
if root:IsA("GuiObject") then
local rp = root.AbsolutePosition local rs = root.AbsoluteSize
if rs.X > 20 and rs.Y > 20 then
targetX = rp.X + rs.X * 0.50 targetY = rp.Y + rs.Y * 0.56 end end local candidates = {}
if root:IsA("GuiObject") and State.coinVisible(root) then
table.insert(candidates, root) end for _, obj in ipairs(root:GetDescendants()) do
if obj:IsA("GuiObject") and State.coinVisible(obj) then
table.insert(candidates, obj) end end local bestObject = nil local bestButton = nil
local bestScore = -math.huge for _, obj in ipairs(candidates) do
local size = obj.AbsoluteSize local pos = obj.AbsolutePosition
if size.X >= 36 and size.Y >= 36 then
local ratio = size.Y > 0 and size.X / size.Y or 99 if ratio >= 0.58 and ratio <= 1.72 then
local cx = pos.X + size.X * 0.5 local cy = pos.Y + size.Y * 0.5 local dx = cx - targetX
local dy = cy - targetY local distance = math.sqrt(dx * dx + dy * dy)
local area = size.X * size.Y local lowName = string.lower(tostring(obj.Name or ""))
local objText = "" if obj:IsA("TextButton") or obj:IsA("TextLabel") then
objText = string.lower(tostring(obj.Text or "")) end
local score = math.max(0, 650 - distance * 2.0) if obj:IsA("ImageButton") then
