elseif obj:IsA("ImageLabel") then
score += 360
elseif obj:IsA("TextButton") then
score += 220
else
score += 40 end if area >= 4500 and area <= 60000 then
score += math.min(420, area / 85)
elseif area > 60000 then
score -= 240 end
if string.find(lowName, "rocoin", 1, true) or string.find(lowName, "coin", 1, true)
or string.find(objText, "rocoin", 1, true) or string.find(objText, "coin", 1, true) then
score += 900 end local clickable = nil if obj:IsA("GuiButton") then
clickable = obj
else
local parent = obj.Parent while parent and parent ~= gui do
if parent:IsA("GuiButton") then
clickable = parent break end parent = parent.Parent end end if clickable then
score += 260 end if score > bestScore then
bestScore = score bestObject = obj bestButton = clickable end end end end
runtime.Target = bestObject
if bestButton and bestButton.Parent and State.coinVisible(bestButton) then
