State.probeRoCoinsClickBackend = function() local runtime = State.CCAutoClick
local backend = runtime.Executor if backend.Probed then
return backend end backend.Probed = true pcall(function()
if type(mousemoveabs) == "function" then
backend.MouseMove = mousemoveabs end if type(mousemoverel) == "function" then
backend.MouseMoveRel = mousemoverel end if type(mouse1click) == "function" then
backend.MouseClick = mouse1click end if type(mouse1press) == "function" then
backend.MousePress = mouse1press end if type(mouse1release) == "function" then
