backend.VIM = game:GetService("VirtualInputManager") end) return backend end
State.sendAlignedRoCoinsClick = function(x, y, requireCursor)
x, y = math.floor(x + 0.5), math.floor(y + 0.5) local camera = workspace.CurrentCamera
local view = camera and camera.ViewportSize
if view and (x < 0 or x > view.X or y < 0 or y > view.Y + 64) then
return false, "FORA DA TELA" end local backend = State.probeRoCoinsClickBackend()
local function cursorAligned() local found = UserInputService:GetMouseLocation()
return math.abs(x - found.X) <= 5 and math.abs(y - found.Y) <= 5 end
local aligned = cursorAligned() if not aligned and backend.MouseMove then
local movedX, movedY = x, y for attempt = 1, 5 do
if not pcall(backend.MouseMove, movedX, movedY) then break end task.wait(0.016)
local found = UserInputService:GetMouseLocation() local dx, dy = x - found.X, y - found.Y
if math.abs(dx) <= 5 and math.abs(dy) <= 5 then
aligned = true break end
if view and (math.abs(dx) > view.X or math.abs(dy) > view.Y) then break end
movedX = math.floor(movedX + dx + 0.5) movedY = math.floor(movedY + dy + 0.5) end end
if not aligned and backend.MouseMoveRel then
for attempt = 1, 5 do
local found = UserInputService:GetMouseLocation() local dx, dy = x - found.X, y - found.Y
if math.abs(dx) <= 5 and math.abs(dy) <= 5 then
aligned = true break end
if view and (math.abs(dx) > view.X or math.abs(dy) > view.Y) then break end
if not pcall(backend.MouseMoveRel, math.floor(dx + 0.5), math.floor(dy + 0.5)) then break end
task.wait(0.016) end end aligned = aligned or cursorAligned()
if requireCursor and not aligned then
return false, "CURSOR NAO ALINHADO" end if aligned then
if backend.MouseClick and pcall(backend.MouseClick) then
return true, "MOUSE1CLICK ALINHADO" end
if backend.MousePress and backend.MouseRelease then
local ok = pcall(function() backend.MousePress() task.wait(0.012)
backend.MouseRelease() end)
if ok then return true, "MOUSE PRESS/RELEASE ALINHADO" end end end if requireCursor then
if backend.VIM then
local ok = pcall(function() backend.VIM:SendMouseButtonEvent(x, y, 0, true, game, 0)
task.wait(0.012) backend.VIM:SendMouseButtonEvent(x, y, 0, false, game, 0) end)
if ok then return true, "VIM NO R$ ALINHADO" end end
return false, "CLIQUE FISICO INDISPONIVEL" end if backend.VIM then
local ok = pcall(function() backend.VIM:SendMouseMoveEvent(x, y, game) task.wait(0.004)
backend.VIM:SendMouseButtonEvent(x, y, 0, true, game, 0) task.wait(0.012)
backend.VIM:SendMouseButtonEvent(x, y, 0, false, game, 0) end)
if ok then return true, "VIRTUAL INPUT" end end if VirtualUser then
local ok = pcall(function() local point = Vector2.new(x, y)
local cameraCFrame = camera and camera.CFrame or CFrame.new()
VirtualUser:CaptureController() VirtualUser:Button1Down(point, cameraCFrame)
task.wait(0.018) VirtualUser:Button1Up(point, cameraCFrame) end)
if ok then return true, "VIRTUAL USER" end end
return false, "POSICAO OU CLIQUE NAO DISPONIVEL" end
State.clickRoCoinsTarget = function(forceSilent)
if not State.isCoinClickerLaptopEquipped() then
