local runtime = State.CCAutoClick
local position = State.captureNativeRoCoinsClickPosition()
if typeof(position) ~= "Vector2" then return false end
local x = math.floor(position.X + 0.5) local y = math.floor(position.Y + 0.5)
local clicked, method = State.sendAlignedRoCoinsClick(x, y) runtime.LastBackend = method
return clicked end State.MiniCoinClickerKEnabled = true
State.MiniCoinClickerKPrevious = nil
-- O mini painel grafico foi removido; o modo silencioso permanece no motor Auto RoCoins.
do
    -- Limpa o painel deixado por execucoes anteriores, sem tocar nas demais UIs.
    local previous = playerGui:FindFirstChild("UnicornHubMiniRoCoins")
    if previous then previous:Destroy() end
    if State.IsRoVibes and State.Plus.IsOwner then
        local mini = {Connections = {}, CharacterConnections = {}, Tool = nil, Stopped = false}
        State.CoinClickerMiniAutoToggle = mini
        State.CoinClickerMiniRoCoins = mini

        local function track(connection, list)
            table.insert(list or mini.Connections, connection)
            return connection
        end
        local function clearCharacterConnections()
            for _, connection in ipairs(mini.CharacterConnections) do
                pcall(function() connection:Disconnect() end)
            end
            table.clear(mini.CharacterConnections)
        end
        local function findOwnedLaptop()
            local character = player.Character
            local backpack = player:FindFirstChildOfClass("Backpack")
            local equippedTool = State.coinClickerFarmFindLaptop(character, nil)
            if equippedTool then return equippedTool, true end
            local backpackTool = State.coinClickerFarmFindLaptop(nil, backpack)
            if backpackTool then return backpackTool, false end
            return nil, false
        end
        local function collecting()
            local farms = State.Exploit
            return farms and ((farms.TeleportCandie and farms.TeleportCandie.Enabled)
                or (farms.PotionFarm and farms.PotionFarm.Enabled))
        end
        local lastFarmUnequip = -math.huge
        local lastDriverAttempt = -math.huge
        local function update()
            if mini.Stopped or not State.Running then return end
            local tool, equipped = findOwnedLaptop()
            local open = isCoinClickerMenuOpen()
            if open then State.captureNativeRoCoinsClickPosition() end
            if tool and equipped and collecting() and not open
                and not State.coinClickerFarmShouldHoldLaptop()
                and State.Running and State.CoinClickerMiniRoCoinsEnabled
                and os.clock() - lastFarmUnequip >= 1.0 then
                lastFarmUnequip = os.clock()
                local character = player.Character
                local humanoid = character and character:FindFirstChildOfClass("Humanoid")
                if humanoid and humanoid.Health > 0 then
                    pcall(function() humanoid:UnequipTools() end)
                    tool, equipped = findOwnedLaptop()
                end
            end
            local enabled = State.Running and State.CoinClickerMiniRoCoinsEnabled
                and State.MiniCoinClickerKEnabled ~= false and tool ~= nil
            mini.Tool = tool
            -- Status logico usado pelo Stamina Safe, tecla K e motor de cliques.
            State.CoinClickerMiniButtonEquipped = enabled == true
            -- Sem tela, botoes ou movimetacao de mouse: o driver continua invisivel.
            if enabled and equipped and not open and State.AutoRoCoins and State.Plus.Enabled then
                local now = os.clock()
                if now - lastDriverAttempt >= (isMobile and 1.3 or 0.9) then
                    lastDriverAttempt = now
                    State.ensureCoinClickerBackgroundDriver()
                end
            elseif not (CoinClickerAutoEnabled and State.CoinClickerSilentEnabled)
                and State.CoinClickerBackground and State.CoinClickerBackground.Owned then
                State.stopCoinClickerBackgroundDriver()
            end
        end
        mini.refreshNow = update
        -- O clique real fica em State.stepRoCoins/State.clickRoCoinsTarget.
        -- Nao emitir outro clique pelo cursor para um botao que nao existe.
        mini.sendMouseClick = function() return false end
        mini.stop = function()
            if mini.Stopped then return end
            mini.Stopped = true
            State.CoinClickerMiniButtonEquipped = false
            clearCharacterConnections()
            for _, connection in ipairs(mini.Connections) do
                pcall(function() connection:Disconnect() end)
            end
            table.clear(mini.Connections)
        end
        local function watchCharacter(character)
            clearCharacterConnections()
            if character then
                track(character.ChildAdded:Connect(update), mini.CharacterConnections)
                track(character.ChildRemoved:Connect(update), mini.CharacterConnections)
            end
            update()
        end
        track(player.CharacterAdded:Connect(watchCharacter))
        track(player.CharacterRemoving:Connect(function()
            clearCharacterConnections()
            State.CoinClickerMiniButtonEquipped = false
        end))
        watchCharacter(player.Character)
        task.spawn(function()
            while State.Running and not mini.Stopped do
                update()
                task.wait(isMobile and 1.2 or 0.8)
            end
        end)
    end
end
State.stepRoCoins = function(now, forceSilent, scanAutoClick)
if not State.isCoinClickerLaptopEquipped() then return false end
if not (not State.AutoRoCoins and not scanAutoClick) then
return false end local runtime = State.CCAutoClick
if forceSilent and State.CoinClickerBackground and State.CoinClickerBackground.Driver then
if now - runtime.LastStaminaCheck >= math.max(0.40, runtime.StaminaCheckInterval) then
runtime.LastStaminaCheck = now local percent = State.getStaminaPercent(false)
if percent ~= nil then
runtime.StaminaPercent = math.clamp(percent, 0, 100) end end
local recent = now - (runtime.LastStaminaRead or 0) <= 2.0
local stamina = recent and runtime.StaminaPercent or nil if runtime.PausedForStamina then
if stamina == nil or stamina < runtime.ResumeAt then return false end
runtime.PausedForStamina = false
elseif stamina ~= nil and stamina <= runtime.PauseAt then
runtime.PausedForStamina = true return false end return State.clickRoCoinsTarget(true) end
if now - runtime.LastStaminaCheck >= runtime.StaminaCheckInterval then
runtime.LastStaminaCheck = now local stamina = State.getStaminaPercent(true)
if stamina ~= nil then
runtime.StaminaPercent = math.clamp(stamina, 0, 100) end end
local stamina = runtime.StaminaPercent if stamina == nil then
if (State.CoinClickerSilentPass or forceSilent) and State.CoinClickerBackground
and State.CoinClickerBackground.Driver then
return State.clickRoCoinsTarget(true) end return false end
if runtime.PausedForStamina then
if stamina < 99.5 then
return false end runtime.PausedForStamina = false
elseif stamina <= 0.5 then
runtime.PausedForStamina = true return false end return State.clickRoCoinsTarget() end
State.CoinClickerAnywhereClickConnection = UserInputService.InputBegan:Connect(function(input, processed)
if processed or not State.Running or not State.IsRoVibes then return end
if input.UserInputType ~= Enum.UserInputType.MouseButton1
and input.UserInputType ~= Enum.UserInputType.Touch then return end
if not State.AutoRoCoins or not State.coinClickerNoNativeMenu()
or not State.isCoinClickerLaptopEquipped() or Safety.Paused or State.ManualPaused then return end
local farmActive = State.Exploit.TeleportCandie.Enabled or State.Exploit.PotionFarm.Enabled
if farmActive and not State.coinClickerFarmCanClick() then return end
local now = os.clock()
local runtime = State.CCAutoClick
if now - runtime.LastManualClick < 0.03 then return end
runtime.LastManualClick = now
task.defer(function()
if State.Running and State.AutoRoCoins and State.isCoinClickerLaptopEquipped() then
pcall(State.stepRoCoins, os.clock(), true, true) end end)
end)
