State.joinRoVibesPlayerServer = function(username) username = tostring(username or "" )
:gsub("^%s+", "")
:gsub("%s+$", "")
:gsub("^@", "") if username == "" then
return false, "Digite o username" end local targetUserId = tonumber(username)
if not targetUserId then
local okUserId, userIdOrError = pcall(function()
return Players:GetUserIdFromNameAsync(username) end) if not okUserId then
warn("[Unicorn Hub] Username não encontrado:", userIdOrError)
return false, "Username inválido" end targetUserId = tonumber(userIdOrError) end
if not targetUserId or targetUserId <= 0 then
return false, "UserId inválido" end if targetUserId == player.UserId then
return false, "Esse é você" end
local targetInServer = Players:GetPlayerByUserId(targetUserId) if targetInServer then
return true, "Já está aqui" end local requestFn = getRequestFunction()
if not requestFn then
warn("[Unicorn Hub] Executor sem request/http_request para Presence API." )
return false, "HTTP indisponível" end
local body = HttpService:JSONEncode({ userIds = { targetUserId, }, })
local requestOk, response = pcall(function()
return requestFn({ Url = "https://presence.roblox.com/v1/presence/users", Method = "POST",
Headers = { ["Content-Type"] = "application/json", ["Accept"] = "application/json", },
Body = body, }) end) if not requestOk or type(response) ~= "table" then
warn("[Unicorn Hub] Falha ao consultar Presence API:", response)
return false, "Falha ao localizar" end
local statusCode = tonumber(response.StatusCode or response.Status or response.status or 0) or 0
local responseBody = response.Body or response.body or response.ResponseBody
if statusCode ~= 0 and (statusCode < 200 or statusCode >= 300) then
warn("[Unicorn Hub] Presence API HTTP " .. tostring(statusCode))
return false, "Presence HTTP " .. tostring(statusCode) end
if type(responseBody) ~= "string" or responseBody == "" then
return false, "Resposta vazia" end
local decodeOk, decoded = pcall(HttpService.JSONDecode, HttpService, responseBody)
if not decodeOk or type(decoded) ~= "table" then
return false, "Resposta inválida" end local presences = decoded.userPresences
local presence = type(presences) == "table" and presences[1] or nil
if type(presence) ~= "table" then
return false, "Sem presença" end
local presenceType = tonumber(presence.userPresenceType) or 0 if presenceType ~= 2 then
if presenceType == 0 then
return false, "Player offline"
elseif presenceType == 1 then
return false, "Player no site"
elseif presenceType == 3 then
return false, "Player no Studio"
else
return false, "Player indisponível" end end local placeId = tonumber(presence.placeId)
local jobId = tostring(presence.gameId or "" )
if not placeId or placeId <= 0 or jobId == "" or jobId == "nil" then
return false, "Servidor privado/oculto" end
if placeId == game.PlaceId and jobId == game.JobId then
return true, "Já está aqui" end pcall(ServerBrowserCache.queueUnicornHubAfterTeleport)
local teleportOk, teleportError = pcall(function()
TeleportService:TeleportToPlaceInstance(placeId, jobId, player) end)
if not teleportOk then
warn("[Unicorn Hub] Falha ao entrar no servidor de " .. username .. ":", teleportError)
return false, "Falha no teleport" end return true, "Entrando..." end
do
    local followRunning = false
    local followLastTarget = ""
    local followLastAt = -math.huge

    local function showFollowMessage(message, isError)
        local formatted = "[Unicorn Hub /follow] " .. tostring(message)
        if isError then warn(formatted) else print(formatted) end
        pcall(function()
            game:GetService("StarterGui"):SetCore("SendNotification", {
                Title = "Unicorn Hub /follow",
                Text = tostring(message),
                Duration = 4,
            })
        end)
    end

    local function handleFollowChat(rawText)
        if not State.Running then return end
        local alias, argument = tostring(rawText or ""):match("^%s*/([%a]+)%s*(.-)%s*$")
        if not alias then return end
        alias = string.lower(alias)
        if alias ~= "follow" and alias ~= "seguir" then return end
        argument = tostring(argument or ""):gsub("^@", "")
        if argument == "" then
            showFollowMessage("Use /follow @usuario ou /follow ID", true)
            return
        end
        if #argument > 32 or not argument:match("^[%w_]+$") then
            showFollowMessage("Informe um username ou UserId valido", true)
            return
        end
        local now = os.clock()
        if followRunning then return end
        if followLastTarget == argument and now - followLastAt < 2 then return end
        followLastTarget, followLastAt = argument, now
        followRunning = true
        task.spawn(function()
            local callOk, success, status = pcall(function()
                return State.joinRoVibesPlayerServer(argument)
            end)
            followRunning = false
            if not State.Running then return end
            if not callOk then
                showFollowMessage("Nao foi possivel iniciar o follow", true)
                warn("[Unicorn Hub /follow] Falha:", success)
            else
                showFollowMessage(status or (success and "Teleport solicitado" or "Jogador indisponivel"), not success)
            end
        end)
    end

    pcall(function()
        local chat = game:GetService("TextChatService")
        local previous = chat:FindFirstChild("__UnicornHubFollowChat")
        if previous then previous:Destroy() end
        local command = Instance.new("TextChatCommand")
        command.Name = "__UnicornHubFollowChat"
        command.PrimaryAlias = "/follow"
        command.SecondaryAlias = "/seguir"
        command.Parent = chat
        ServerBrowserCache.extraTextCommands = ServerBrowserCache.extraTextCommands or {}
        ServerBrowserCache.extraTextCommandConnections = ServerBrowserCache.extraTextCommandConnections or {}
        table.insert(ServerBrowserCache.extraTextCommands, command)
        table.insert(ServerBrowserCache.extraTextCommandConnections,
            command.Triggered:Connect(function(originTextSource, unfilteredText)
                if originTextSource and originTextSource.UserId ~= player.UserId then return end
                handleFollowChat(unfilteredText)
            end))
    end)
    pcall(function()
        local connection = player.Chatted:Connect(handleFollowChat)
        ServerBrowserCache.extraTextCommandConnections = ServerBrowserCache.extraTextCommandConnections or {}
        table.insert(ServerBrowserCache.extraTextCommandConnections, connection)
    end)
end
State.teleportRoVibes = function(position) if typeof(position) ~= "Vector3" then
