if not character or not humanoid or humanoid.Health <= 0 or not root then
warn("[Unicorn Hub] Personagem indisponível para teleportar.") return false end
local rotation = root.CFrame - root.CFrame.Position local ok, err = pcall(function()
character:PivotTo(CFrame.new(position) * rotation) end) if not ok then
warn("[Unicorn Hub] Falha no teleport RoVibes:", err) return false end return true end
