local targetRoot = targetCharacter:FindFirstChild("HumanoidRootPart")
or targetCharacter:FindFirstChild("Torso") or targetCharacter:FindFirstChild("UpperTorso")
local myRoot = myCharacter:FindFirstChild("HumanoidRootPart") or myCharacter:FindFirstChild("Torso")
or myCharacter:FindFirstChild("UpperTorso") if not targetRoot or not myRoot then
warn("[Unicorn Hub] RootPart não encontrado para GOTO.") return false end
local destination = targetRoot.CFrame * CFrame.new(3, 0, 0)
