or currentTargetCharacter:FindFirstChild("UpperTorso"))
if not currentMyCharacter or not currentHumanoid or currentHumanoid.Health <= 0
or not currentRoot or currentRoot ~= BackpackRideSaved.root or not currentTargetCharacter
or not currentTargetHumanoid or currentTargetHumanoid.Health <= 0 or not currentTargetRoot
