or name == "AdminDockHeader"
or name == "MobileMovementDock" or instance == U.mobileDock then
target = profile.side
elseif name == "PlayersDock" or name == "AdminDock"
or name == "CoinClickerDock" or name == "UnicornHubPlayerQuickMenu" then
target = profile.dock
elseif instance.BackgroundTransparency < 0.82 then
local color = instance.BackgroundColor3 if color == C.bg then
target = profile.clip
elseif color == C.side then
target = profile.side
elseif color == C.panel then
target = profile.panel
elseif color == C.card or color == C.cardHover then
target = profile.card
elseif name == "PlusUserCard" or instance:GetAttribute("PlayerCard") == true then
