U.isHubIconAsset = function(instance)
if not (instance:IsA("ImageLabel") or instance:IsA("ImageButton")) then return false end
local image = tostring(instance.Image or "") if image == "" then return false end
local name = string.lower(tostring(instance.Name))
if name:find("avatar", 1, true) or name:find("headshot", 1, true)
or name:find("portrait", 1, true) or name:find("thumbnail", 1, true) then
return false end return image:find("rbxassetid://", 1, true) ~= nil
or image:find("rbxthumb://type=Asset", 1, true) ~= nil end
U.recolorHubIcon = function(instance) if not U.isHubIconAsset(instance) then return end
local theme = State.getGraphicsTheme and State.getGraphicsTheme() or "Dark UI (Normal)"
local palette = State.getHubThemeColors and State.getHubThemeColors() or C
instance.ImageColor3 = theme == "Light UI (Branco)"
and Color3.fromRGB(0, 0, 0) or palette.white end U.recolorHubIcons = function()
if not Gui or not Gui.Parent then return end for _, obj in ipairs(Gui:GetDescendants()) do
if obj:IsA("ImageLabel") or obj:IsA("ImageButton") then
U.recolorHubIcon(obj) end end if U.connectedDot and U.connectedDot.Parent then
local theme = State.getGraphicsTheme and State.getGraphicsTheme() or "Dark UI (Normal)"
local palette = State.getHubThemeColors and State.getHubThemeColors() or C
U.connectedDot.BackgroundColor3 = theme == "Light UI (Branco)"
and Color3.fromRGB(0, 0, 0) or palette.white end end U.applyGraphicsTheme = function()
if not Gui or not Gui.Parent or not State.getHubThemeColors then
return end local incoming = State.getHubThemeColors() local previous = {}
for role, color in pairs(C) do
previous[role] = color end
if previous.bg == incoming.bg and previous.white == incoming.white
and previous.neon == incoming.neon and previous.border == incoming.border then
U.recolorHubIcons() return end
local roles = { "side", "panel", "card", "cardHover", "border", "borderSoft",
"text", "text2", "muted", "dim", "white", "off", "neon", "neonSoft", "bg", "black", }
local function convert(color, property)
if previous.bg == previous.black and color == previous.bg then
return property == "TextColor3" and incoming.black or incoming.bg end
for _, role in ipairs(roles) do
if color == previous[role] then
return incoming[role] end end return nil end local function swap(instance, property)
local ok, value = pcall(function() return instance[property] end) if not ok then
return end local updated = convert(value, property) if updated and updated ~= value then
pcall(function() instance[property] = updated end) end end
for _, instance in ipairs(Gui:GetDescendants()) do
if instance.Name == "__UnicornHubFlowOutline"
or instance:FindFirstAncestor("__UnicornHubFlowOutline") then
continue end if instance:IsA("GuiObject") then
swap(instance, "BackgroundColor3") if instance.Name == "UnicornHubPlusAccessBadge" then
instance.TextColor3 = Color3.fromRGB(255, 255, 255)
elseif instance:IsA("TextLabel") or instance:IsA("TextButton") or instance:IsA("TextBox") then
swap(instance, "TextColor3") if instance:IsA("TextBox") then
swap(instance, "PlaceholderColor3") end end
if instance:IsA("ImageLabel") or instance:IsA("ImageButton") then
swap(instance, "ImageColor3") end if instance:IsA("ScrollingFrame") then
swap(instance, "ScrollBarImageColor3") end
elseif instance:IsA("UIStroke") then
swap(instance, "Color")
elseif instance:IsA("UIGradient") and instance.Name ~= "PlusNeonAnimatedGradient" then
local points = instance.Color.Keypoints local updatedPoints = {} local changed = false
for _, point in ipairs(points) do
local nextColor = convert(point.Value, "GradientColor") or point.Value
if nextColor ~= point.Value then
changed = true end
table.insert(updatedPoints, ColorSequenceKeypoint.new(point.Time, nextColor)) end
if changed then
instance.Color = ColorSequence.new(updatedPoints) end end end
for role, color in pairs(incoming) do
C[role] = color end U.recolorHubIcons()
local usePlus = State.isPlusThemeActive and State.isPlusThemeActive() or false
