local function toggleVisual(track, knob, on)
local targetTrackColor = on and C.white or C.off
local targetKnobColor = on and C.black or C.white
local targetPosition = on and UDim2.new(1, -17, 0.5, -7) or UDim2.new(0, 3, 0.5, -7)
State.uiTween(track, TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
BackgroundColor3 = targetTrackColor })
State.uiTween(knob, TweenInfo.new(0.14, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
BackgroundColor3 = targetKnobColor, Position = targetPosition })
local knobScale = knob:FindFirstChild("__UnicornHubToggleScale") if not knobScale then
knobScale = Instance.new("UIScale") knobScale.Name = "__UnicornHubToggleScale"
knobScale.Scale = 1 knobScale.Parent = knob end knobScale.Scale = 0.84
State.uiTween(knobScale, TweenInfo.new(0.09, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
Scale = 1.12 }) task.delay(0.085, function() if knobScale and knobScale.Parent then
State.uiTween(knobScale, TweenInfo.new(0.08, Enum.EasingStyle.Quad,
Enum.EasingDirection.Out), { Scale = 1 }) end end) end
local function bindToggleHover(track, knob) if isMobile then
return end local trackScale = Instance.new("UIScale")
trackScale.Name = "__UnicornHubToggleHoverScale" trackScale.Scale = 1
trackScale.Parent = track track.MouseEnter:Connect(function()
State.uiTween(trackScale, TweenInfo.new(0.10, Enum.EasingStyle.Quad, Enum.EasingDirection.Out
), { Scale = 1.10 })
State.uiTween(knob, TweenInfo.new(0.10, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
Rotation = 4 }) end) track.MouseLeave:Connect(function()
State.uiTween(trackScale, TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out
), { Scale = 1 })
State.uiTween(knob, TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
Rotation = 0 }) end) end U.requiresPlus = function(page, titleText, key)
return false end
