local function setPage(name) if name == "RoVibes" and not State.IsRoVibes then
name = "Main" end if name == "Blade Ball" and not State.IsBladeBall then
name = "Main" end if name == "The Rake" and not State.IsTheRake then
name = "Main" end if isMobile and name == "Hotkeys" then
name = "Main" end if name == "Plus" and not State.IsRoVibes then
name = "Main" end if name == "Coin Clicker" then
if not isMobile or not State.Plus.IsOwner or not State.IsRoVibes then
name = "Main" end end
if (name == "ADD +" or name == "Admin" ) and not State.Plus.IsOwner then
name = "Main" end if isMobile and name ~= "Coin Clicker" then
State.CoinClickerPanelOpen = false end U.currentPage = name saveSetting("LastPage", name)
if name == "Admin" then
task.defer(function()
if State.Running and U.currentPage == "Admin" then
if U.refreshAdminPlayers then pcall(U.refreshAdminPlayers) end
if U.refreshApiHubUsers then pcall(U.refreshApiHubUsers) end
end
end)
end
Title.Text = name if U.mobilePlayersSearchWrap then
U.mobilePlayersSearchWrap.Visible = name == "Jogadores"
if name ~= "Jogadores" and U.playersSearch
and UserInputService:GetFocusedTextBox() == U.playersSearch then
U.playersSearch:ReleaseFocus() end end for pageName, page in pairs(U.pages) do
if not isMobile and pageName == "Jogadores" then
