local function setFromHex(value) local normal = State.normalizeGraphicsHex(value)
if not normal then return false end
local color = Color3.fromRGB(tonumber(normal:sub(2, 3), 16),
tonumber(normal:sub(4, 5), 16), tonumber(normal:sub(6, 7), 16))
h, s, v = color:ToHSV() updateVisual() return true end
local function samplePointer(target, vec) if not target.Parent then return end
local pos, size = target.AbsolutePosition, target.AbsoluteSize
if size.X <= 0 or size.Y <= 0 then return end
local x = math.clamp((vec.X - pos.X) / size.X, 0, 1) if target == svHit then
s = x v = 1 - math.clamp((vec.Y - pos.Y) / size.Y, 0, 1)
else
h = x end updateVisual() end local dragTarget, dragTouch
local function beginDrag(target, input) local kind = input.UserInputType
if kind ~= Enum.UserInputType.MouseButton1
and kind ~= Enum.UserInputType.Touch then return end dragTarget = target
dragTouch = kind == Enum.UserInputType.Touch and input or nil
local p = kind == Enum.UserInputType.MouseButton1
and UserInputService:GetMouseLocation() or input.Position samplePointer(target, p) end
svHit.InputBegan:Connect(function(input) beginDrag(svHit, input) end)
hueBar.InputBegan:Connect(function(input) beginDrag(hueBar, input) end)
local motion = UserInputService.InputChanged:Connect(function(input)
if not dragTarget then return end if dragTouch then
if input.UserInputType ~= Enum.UserInputType.Touch then return end
if input ~= dragTouch then return end samplePointer(dragTarget, input.Position)
elseif input.UserInputType == Enum.UserInputType.MouseMovement then
samplePointer(dragTarget, UserInputService:GetMouseLocation()) end end)
local release = UserInputService.InputEnded:Connect(function(input) if dragTouch then
if input == dragTouch then dragTarget, dragTouch = nil, nil end
elseif input.UserInputType == Enum.UserInputType.MouseButton1 then
dragTarget, dragTouch = nil, nil end end) pickerGui.Destroying:Connect(function()
motion:Disconnect() release:Disconnect()
dragTarget, dragTouch = nil, nil end) pickerInput.FocusLost:Connect(function()
