if child ~= Gui and (string.find(lower, "loading", 1, true)
or string.find(lower, "loader", 1, true)) then
pcall(function() child:Destroy() end) end end end end end
if State.StartupLoading and State.StartupLoading.Gui and State.StartupLoading.Gui.Parent then
pcall(function() State.StartupLoading.Gui:Destroy() end)
State.StartupLoading.Gui = nil end end customToggleCard(U.miscPage, "Remover Loading",
