local seconds = math.max(0, os.time()
- (tonumber(addedAt) or os.time())) local days = math.floor(seconds / 86400)
local hours = math.floor((seconds % 86400) / 3600)
local minutes = math.floor((seconds % 3600) / 60) if days > 0 then
return tostring(days) .. "d " .. tostring(hours) .. "h" end if hours > 0 then
return tostring(hours) .. "h " .. tostring(minutes) .. "min" end
return tostring(math.max(1, minutes)) .. "min" end U.clearPlusUserCards = function()
