local adminActionIndex = 0
local function adminActionButton(textValue, x, y, width, callback)
adminActionIndex += 1
local actionIndex = adminActionIndex
local column = (actionIndex - 1) % 2
local row = math.floor((actionIndex - 1) / 2)
local featured = actionIndex == 1 or actionIndex == 8
local button = Instance.new("TextButton")
button.Name = "AdminAction_" .. string.gsub(textValue, "[^%w]", "")
button.Size = UDim2.new(0.5, -18, 0, 36)
button.Position = column == 0 and UDim2.fromOffset(12, 85 + row * 42)
    or UDim2.new(0.5, 6, 0, 85 + row * 42)
button.BackgroundColor3 = featured and Color3.fromRGB(245, 245, 247)
    or Color3.fromRGB(27, 27, 33)
button.TextColor3 = featured and Color3.fromRGB(13, 13, 17)
    or Color3.fromRGB(247, 247, 249)
button.Text = textValue
button.TextSize = isMobile and 9 or 10
button.Font = Enum.Font.GothamBold
button.BorderSizePixel = 0
button.AutoButtonColor = false
button.Parent = card
corner(button, 9)
if not featured then stroke(button, Color3.fromRGB(52, 52, 62), 1, 0.18) end
if not isMobile and not State.Performance.LowEnd then
    button.MouseEnter:Connect(function()
        if button.Parent then
            State.uiTween(button, TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                {BackgroundColor3 = featured and Color3.fromRGB(222, 222, 228) or Color3.fromRGB(41, 41, 49)})
        end
    end)
    button.MouseLeave:Connect(function()
        if button.Parent then
            State.uiTween(button, TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                {BackgroundColor3 = featured and Color3.fromRGB(245, 245, 247) or Color3.fromRGB(27, 27, 33)})
        end
    end)
end
if U.bindSound then U.bindSound(button) end
button.Activated:Connect(function()
    if not button.Parent or not State.Running then return end
    task.spawn(function()
        local ok, err = pcall(callback)
        if not ok then
            warn("[Unicorn Hub] Erro no botao ADM " .. tostring(textValue) .. ":", tostring(err))
            if button.Parent then
                adminStatus("Falha na opcao " .. tostring(textValue) .. ".", false)
            end
        end
    end)
end)
return button
end
