if entry and os.clock()
- (tonumber(entry.LastSeen) or 0) <= 14 then
table.insert(list, targetPlayer) end end end table.sort(list, function(a, b)
return string.lower(a.DisplayName or a.Name)
< string.lower(b.DisplayName or b.Name) end
)
