    local entry = State.Admin.HubUsers[tostring(targetPlayer.UserId)]
    signatureParts[#signatureParts + 1] = tostring(targetPlayer.UserId) .. ":"
        .. tostring(targetPlayer.DisplayName) .. ":"
        .. tostring(entry and entry.Plus == true) .. ":"
        .. tostring(entry and entry.AllowAdmin == true)
end
local signature = table.concat(signatureParts, "|")
if U.AdminPlayersLastSignature == signature
    and U.adminPlayersHolder:GetAttribute("AdminCardsInitialized") == true then
    return
end
U.adminPlayersHolder:SetAttribute("AdminCardsInitialized", false)
U.clearAdminPlayerCards()
for index, targetPlayer in ipairs(list) do
U.makeAdminPlayerCard(targetPlayer, index) end if #list == 0 then
