local function normalize(textValue)
local raw = tostring(textValue or ""):gsub("^%s+", ""):gsub("%s+$", "")
raw = raw:gsub("^@", "") return raw end local function findIgnoredByName(raw)
local lower = string.lower(raw) for id, name in pairs(aimIgnore.IgnoredUserIds) do
if string.lower(tostring(name)) == lower then return id, name end end return nil end
local function resolveUser(raw, removing)
if raw == "" then return nil, nil, "Digite um jogador." end local id = tonumber(raw)
if id and id > 0 and id == math.floor(id) then
local current = Players:GetPlayerByUserId(id)
return id, current and current.Name or tostring(id) end if removing then
local ignoredId, ignoredName = findIgnoredByName(raw)
if ignoredId then return ignoredId, ignoredName end end local exactUser local exactDisplay
local displayAmbiguous = false local lower = string.lower(raw)
for _, candidate in ipairs(Players:GetPlayers()) do
if string.lower(candidate.Name) == lower then
exactUser = candidate break
elseif string.lower(candidate.DisplayName) == lower then
if exactDisplay then displayAmbiguous = true end exactDisplay = candidate end end
if exactUser then return exactUser.UserId, exactUser.Name end
if exactDisplay and not displayAmbiguous then
return exactDisplay.UserId, exactDisplay.Name end if displayAmbiguous then
return nil, nil, "Nome repetido. Use @usuario." end local ok, fetchedId = pcall(function()
return Players:GetUserIdFromNameAsync(raw) end)
if ok and tonumber(fetchedId) then return fetchedId, raw end
return nil, nil, "Usuario nao encontrado." end local busy = false
local function updateIgnore(ignored) if busy then return end busy = true
local raw = normalize(input.Text) local id, name, reason = resolveUser(raw, not ignored)
if id and State.setLaserGunIgnored(id, name, ignored) then
status.Text = ignored and ("Mira desativada para @" .. name)
or ("Mira liberada para @" .. name) input.Text = ""
else
status.Text = reason or "Nao foi possivel atualizar." end refreshIgnoreList()
busy = false end addButton.Activated:Connect(function() updateIgnore(true) end)
removeButton.Activated:Connect(function() updateIgnore(false) end)
input.FocusLost:Connect(function(enterPressed)
if enterPressed then updateIgnore(true) end end) refreshIgnoreList() end
