section(U.plusPage, "Mission Farm", "Resgata recompensas e inicia a próxima missão disponível.")
do
local questAuto = { Enabled = false, Token = 0, Busy = false, RecentAttempts = {},
StartAttempts = {}, UpdateConnection = nil, } State.QuestAutoCollector = questAuto
local function questRemotes()
local remoteRoot = ReplicatedStorage:FindFirstChild("Remotes")
local system = remoteRoot and remoteRoot:FindFirstChild("QuestSystem")
local remotes = system and system:FindFirstChild("Remotes")
local rf = remotes and remotes:FindFirstChild("QuestRF")
local update = remotes and remotes:FindFirstChild("QuestUpdateRE")
if not rf or not rf:IsA("RemoteFunction") then
return nil, nil end if not update or not update:IsA("RemoteEvent") then
update = nil end return rf, update end
local function startNextAvailable(questRF, state, token)
if not State.Running or not questAuto.Enabled or questAuto.Token ~= token
or type(state) ~= "table" or type(state.quests) ~= "table" then return end
for _, quest in ipairs(state.quests) do
if type(quest) == "table" and (type(quest.id) == "string" or
type(quest.id) == "number") then
local status = string.lower(tostring(quest.status or ""))
local available = quest.canStart == true or quest.canAccept == true
or status == "available" or status == "notstarted"
if available and quest.canCollect ~= true then
local key = tostring(quest.id) local now = os.clock()
if now - (questAuto.StartAttempts[key] or -1000) >= 45 then
questAuto.StartAttempts[key] = now local ok, result = pcall(function()
return questRF:InvokeServer("Start", {questId = quest.id}) end)
if not ok or result == false then
warn("[Unicorn Hub] Mission Farm: jogo não aceitou início automático", key) end end
return end end end end local function collectCompleted(state, token)
if not State.Running or not questAuto.Enabled or questAuto.Token ~= token or questAuto.Busy
or type(state) ~= "table" or type(state.quests) ~= "table" then
return end questAuto.Busy = true local claimed = false local questRF = questRemotes()
if questRF then
for _, quest in ipairs(state.quests) do
if not State.Running or not questAuto.Enabled or questAuto.Token ~= token then
break end if type(quest) == "table" and quest.canCollect == true then
local questId = quest.id if type(questId) == "string" or type(questId) == "number" then
local key = tostring(questId) local now = os.clock()
if now - (questAuto.RecentAttempts[key] or -1000) >= 18 then
questAuto.RecentAttempts[key] = now local ok, result = pcall(function()
return questRF:InvokeServer("Collect", { questId = questId, }) end)
if ok and result ~= false then
claimed = true
else
warn("[Unicorn Hub] Mission Farm: falha ao coletar missão:", result) end
task.wait(0.4) end end end end if claimed then
local ok, nextState = pcall(function() return questRF:InvokeServer("GetState", nil) end)
if ok then startNextAvailable(questRF, nextState, token) end end end
questAuto.Busy = false end local function stopQuestCollector() questAuto.Enabled = false
questAuto.Token += 1 if questAuto.UpdateConnection then
questAuto.UpdateConnection:Disconnect() questAuto.UpdateConnection = nil end end
questAuto.Stop = stopQuestCollector local function setQuestCollector(enabled)
enabled = enabled == true if not enabled then
stopQuestCollector() return end if questAuto.Enabled then
return end if not State.Running or not State.IsRoVibes then
return end questAuto.Enabled = true questAuto.Token += 1 questAuto.RecentAttempts = {}
questAuto.StartAttempts = {} local token = questAuto.Token task.spawn(function()
while State.Running and questAuto.Enabled and questAuto.Token == token
do
local questRF, updateRE = questRemotes() if questRF then
if updateRE and not questAuto.UpdateConnection then
questAuto.UpdateConnection = updateRE.OnClientEvent:Connect(
function(kind, updatedState) if kind == "State" and type(updatedState) == "table" then
task.spawn(collectCompleted, updatedState, token) end end
) end local ok, state = pcall(function() return questRF:InvokeServer("GetState", nil) end)
if ok then
collectCompleted(state, token)
else
warn("[Unicorn Hub V87] Falha ao verificar missões:", state) end end
task.wait(12) end end) end customToggleCard(U.plusPage, "Mission Farm", "", function()
return questAuto.Enabled == true end, setQuestCollector) end
