local function collectActive() local found = {}
local folder = workspace:FindFirstChild("LuckyBlocksActive")
if not folder then return found end local character = player.Character
local root = character and character:FindFirstChild("HumanoidRootPart")
local rootPosition = root and root.Position
for index, target in ipairs(folder:GetChildren()) do
local point = nil if target:IsA("BasePart") then
point = target.Position
elseif target:IsA("Model") then
local ok, cf, size = pcall(function() return target:GetBoundingBox() end)
if ok and size and size.Magnitude > 0.1 then
point = cf.Position end end if point then
table.insert(found, { target = target, index = index,
distance = rootPosition and (point - rootPosition).Magnitude or nil }) end end
table.sort(found, function(a, b)
if a.distance and b.distance and math.abs(a.distance - b.distance) > 0.5 then
return a.distance < b.distance end if a.target.Name ~= b.target.Name then
return a.target.Name < b.target.Name end return a.index < b.index end) return found end
