State.scheduleCoinClickerAutoOpen = function() local runtime = State.CCAutoClick
runtime.AutoOpenToken += 1 local token = runtime.AutoOpenToken task.spawn(function()
local deadline = os.clock() + 18
while State.Running and CoinClickerAutoEnabled and token == runtime.AutoOpenToken
and os.clock() < deadline
do
if State.isCoinClickerStartupSafe() then
break end task.wait(0.15) end
if not State.Running or not CoinClickerAutoEnabled or token ~= runtime.AutoOpenToken
or not State.isCoinClickerStartupSafe() then
return end if State.coinClickerNoNativeMenu() then
if CoinClickerAutoEnabled and State.CoinClickerSilentEnabled
and State.prepareCoinClickerSilent then
pcall(State.prepareCoinClickerSilent) end return end local success = false
if openCoinClickerFromHub then
success = openCoinClickerFromHub() end
if not success and State.Running and CoinClickerAutoEnabled and token == runtime.AutoOpenToken
and not State.coinClickerNoNativeMenu() then
task.wait(0.8) if not State.coinClickerNoNativeMenu()
and State.isCoinClickerStartupSafe() and openCoinClickerFromHub then
openCoinClickerFromHub() end end end) end U.addCoinClickerAutoToggle = function(page)
local refresh = customToggleCard(page, "CoinClicker sem abrir laptop",
"Farma RoCoins e compra automaticamente os geradores autorizados (Crystal Ball, Compass e Photo Booth) quando houver saldo. Nao abre a tela do laptop.",
function() return CoinClickerAutoEnabled end, function(value)
if value == true and State.isCoinClickerNativeInterfaceOpen() then
    return
end
CoinClickerAutoEnabled = value == true
State.CoinClickerSilentEnabled = CoinClickerAutoEnabled
if State.refreshCoinClickerNativeMenuGuard then
State.refreshCoinClickerNativeMenuGuard() end
if State.refreshCoinClickerEquippedUIs then
State.refreshCoinClickerEquippedUIs() end
State.CoinClickerSilentStatus = CoinClickerAutoEnabled
and "Aguardando controles do CoinClicker" or "Desligado"
if not CoinClickerAutoEnabled and State.stopCoinClickerBackgroundDriver then
if not State.CoinClickerMiniButtonEquipped then
State.stopCoinClickerBackgroundDriver() end
State.CoinClickerPurchaseStatus = "Desligado" end State.CCAutoClick.AutoOpenToken += 1
if CoinClickerAutoEnabled then
State.AutoRoCoins = true saveSetting("AutoRoCoins", true)
if State.refreshAutoRoCoinsToggle then
pcall(State.refreshAutoRoCoinsToggle) end State.scheduleCoinClickerAutoOpen() end
task.defer(U.refreshCoinClickerAutoToggles) end
) table.insert(U.coinClickerAutoRefreshers, refresh) return refresh end
