U.bindCoinClickerCloseButtons = function() local gui = getGui() if not gui then
return end for _, obj in ipairs(gui:GetDescendants()) do
if obj:IsA("GuiButton") and not U.coinClickerCloseBound[obj] then
local name = string.lower(tostring(obj.Name or "")) local textValue = ""
if obj:IsA("TextButton") then
textValue = string.lower(tostring(obj.Text or "")) end
local isClose = textValue == "x" or textValue == "×" or textValue == "✕"
or textValue == "close" or textValue == "fechar" or string.find(name, "close", 1, true) ~= nil
or string.find(name, "exit", 1, true) ~= nil if isClose then
U.coinClickerCloseBound[obj] = true local connection = obj.Activated:Connect(function()
if State.CoinClickerMenuReturn.Armed then
U.reopenHubFromCoinClickerClose() end end)
table.insert(State.CoinClickerCloseConnections, connection) end end end end
