and os.clock() - api.LastPresenceFetch <= 18 local activePeers = {}
if freshPresence and type(api.PresenceUsers) == "table" then
for _, info in ipairs(api.PresenceUsers) do
local id = tonumber(info.userId) if id and tonumber(info.version) == 401
and tonumber(info.placeId) == game.PlaceId
