U.PlayerTagRows[userId] = nil
else
local active = userId == player.UserId and State.Running and State.UnicornHubTagEnabled
or activePeers[userId] == true local overhead = active and displays and displays[userId]
local source = overhead and overhead.Gui and overhead.Gui.Parent
and overhead.Gui:FindFirstChild("TagLabel", true)
local profile = source and State.getTagStudioConfig(userId) local tagText = nil
if source and source:IsA("TextLabel") then
tagText = tostring(source.Text or "") if profile then
local effect = State.tagStudioEffectId(profile.TagEffect)
local info = State.TagStudio.EffectInfo[effect]
tagText = (info and info.Fixed) or tostring(profile.Tag or tagText) end end
local showTag = active and source ~= nil and tagText ~= nil and tagText ~= ""
row.Value.Visible = showTag == true if showTag then
row.Value.Text = tagText row.Value.AutoLocalize = false
local sourceGradient = source:FindFirstChild("UnicornHubTagGradient")
if sourceGradient and sourceGradient:IsA("UIGradient") then
row.Gradient.Color = sourceGradient.Color row.Gradient.Enabled = true
row.Value.TextColor3 = Color3.new(1, 1, 1)
else
row.Gradient.Enabled = false row.Value.TextColor3 = source.TextColor3 end
else
row.Value.Text = "" row.Gradient.Enabled = false end end end end
