if not (State.Running and State.IsRoVibes and State.Plus.IsOwner) then return end
local keys = {"AutoRoCoins", "AutoFortunes", "AutoBlackMarket"}
if State.MiniCoinClickerKEnabled ~= false then
local previous = {} for _, key in ipairs(keys) do
previous[key] = State[key] == true State[key] = false saveSetting(key, false)
if State.refreshCoinAutoNativeToggle then
pcall(State.refreshCoinAutoNativeToggle, key) end end
State.MiniCoinClickerKPrevious = previous State.MiniCoinClickerKEnabled = false
print("[Unicorn Hub][CoinClicker] K: automáticos PAUSADOS.")
else
local previous = State.MiniCoinClickerKPrevious or {} local hadAny = false
for _, key in ipairs(keys) do
if previous[key] == true then hadAny = true end end for _, key in ipairs(keys) do
State[key] = hadAny and previous[key] == true or not hadAny saveSetting(key, State[key])
if State.refreshCoinAutoNativeToggle then
pcall(State.refreshCoinAutoNativeToggle, key) end end State.MiniCoinClickerKEnabled = true
State.MiniCoinClickerKPrevious = nil
print("[Unicorn Hub][CoinClicker] K: automáticos RESTAURADOS em segundo plano.") end
