local function getUnicornHubLimeColor(now, offset)
local phase = ((tonumber(now) or 0) * 0.7 + (tonumber(offset) or 0)) % 1
local lime = Color3.fromRGB(174, 255, 47) local green = Color3.fromRGB(73, 230, 31)
local glow = Color3.fromRGB(220, 255, 117) if phase < 1 / 3 then
return lime:Lerp(green, phase * 3)
elseif phase < 2 / 3 then
return green:Lerp(glow, (phase - 1 / 3) * 3) end
return glow:Lerp(lime, (phase - 2 / 3) * 3) end
local function getUnicornHubPlusPurpleColor(now, offset)
local phase = ((tonumber(now) or 0) * 0.7 + (tonumber(offset) or 0)) % 1
local purple = Color3.fromRGB(151, 46, 255) local neon = Color3.fromRGB(204, 91, 255)
local glow = Color3.fromRGB(238, 170, 255) if phase < 1 / 3 then
return purple:Lerp(neon, phase * 3)
elseif phase < 2 / 3 then
return neon:Lerp(glow, (phase - 1 / 3) * 3) end
return glow:Lerp(purple, (phase - 2 / 3) * 3) end
