local function speedPhysicsSafe(character, humanoid, root)
if not character or player.Character ~= character or not humanoid or not root
or humanoid.Health <= 0 or root.Anchored or humanoid.Sit or humanoid.SeatPart
or humanoid.PlatformStand or humanoid.FloorMaterial == Enum.Material.Air
or character:GetAttribute("IsCarried") == true
or character:GetAttribute("IsCarrying") == true
or character:GetAttribute("IsMinigame") == true
or character:GetAttribute("RagdollApplied") == true then
return false end local state = humanoid:GetState()
if state == Enum.HumanoidStateType.Physics
or state == Enum.HumanoidStateType.Ragdoll
or state == Enum.HumanoidStateType.FallingDown
or state == Enum.HumanoidStateType.PlatformStanding
or state == Enum.HumanoidStateType.Seated
or state == Enum.HumanoidStateType.Swimming
or state == Enum.HumanoidStateType.Climbing then
return false end local ragdoll = player:GetAttribute("Ragdoll")
if type(ragdoll) == "number" and (ragdoll == -1 or ragdoll > 0) then
return false end if tonumber(character:GetAttribute("CarrierUserId")
or character:GetAttribute("CarriedByUserId") or 0) > 0 then
return false end return true end local function checkMiniature(character, humanoid, root)
local heightScale = humanoid:FindFirstChild("BodyHeightScale")
if heightScale and heightScale:IsA("NumberValue") and heightScale.Value < 0.78 then
return true end if root.Size.Y < 1.55 or (humanoid.RigType == Enum.HumanoidRigType.R15
and humanoid.HipHeight < 1.05) then
return true end local ok, modelScale = pcall(function() return character:GetScale() end)
return ok and type(modelScale) == "number" and modelScale < 0.78 end
local function startSpeedMotion() stopSpeedMotion()
runtime.speedMotionConnection = RunService.Heartbeat:Connect(function(dt)
if not runtime.alive or not runtime.speedEnabled then return end
if State.IsTheRake and State.TheRake and State.TheRake.Options
and State.TheRake.Options.InfiniteStamina then return end
local character = player.Character
local humanoid = character and character:FindFirstChildOfClass("Humanoid")
local root = character and character:FindFirstChild("HumanoidRootPart")
if not humanoid or not root or not root:IsA("BasePart") then return end
local now = os.clock() if runtime.miniatureCharacter ~= character
or now - runtime.lastMiniatureCheck > 0.4 then
runtime.miniatureCharacter = character runtime.lastMiniatureCheck = now
runtime.isMiniature = checkMiniature(character, humanoid, root) end
if not runtime.isMiniature or not speedPhysicsSafe(character, humanoid, root) then
return end local velocity = root.AssemblyLinearVelocity
local flat = Vector3.new(velocity.X, 0, velocity.Z) if flat.Magnitude < 1 then return end
local direction = humanoid.MoveDirection local corrected
if direction.Magnitude > 0.07 then
direction = direction.Unit local forward = flat:Dot(direction)
local sideways = flat - direction * forward
local turnDamping = math.exp(-math.min(dt, 0.08) * 17)
if forward < 0 then forward *= turnDamping end
corrected = direction * forward + sideways * turnDamping
else
corrected = flat * math.exp(-math.min(dt, 0.08) * 20) end
if (flat - corrected).Magnitude > 0.3 then
root.AssemblyLinearVelocity = Vector3.new(corrected.X, velocity.Y, corrected.Z) end end) end
local function applySpeed(character)
if not runtime.speedEnabled or not character then return end
local humanoid = character:FindFirstChildOfClass("Humanoid")
or character:WaitForChild("Humanoid", 5)
if not humanoid or humanoid.Health <= 0 or player.Character ~= character then return end
if State.IsTheRake and State.TheRake and State.TheRake.Options
and State.TheRake.Options.InfiniteStamina then return end
if runtime.speedHumanoid ~= humanoid then
runtime.speedHumanoid = humanoid runtime.savedWalkSpeed = humanoid.WalkSpeed
elseif runtime.savedWalkSpeed == nil then
runtime.savedWalkSpeed = humanoid.WalkSpeed end runtime.speedLastWritten = SPEED_VALUE
UnicornHubHumanoidWrites.set(humanoid, "WalkSpeed", SPEED_VALUE) end
local function restoreSpeed() local humanoid = runtime.speedHumanoid
local target = runtime.savedWalkSpeed
if humanoid and humanoid.Parent and player.Character == humanoid.Parent
and type(target) == "number" and target >= 0 then
local current = humanoid.WalkSpeed
if runtime.speedEnabled or (type(runtime.speedLastWritten) == "number"
and math.abs(current - runtime.speedLastWritten) < 0.1) then
UnicornHubHumanoidWrites.set(humanoid, "WalkSpeed", target) end end
runtime.savedWalkSpeed = nil runtime.speedHumanoid = nil
runtime.speedLastWritten = nil end local function smoothRestoreSpeed() stopSpeedExit()
local character = player.Character
local humanoid = character and character:FindFirstChildOfClass("Humanoid")
if not runtime.alive or not humanoid or humanoid.Health <= 0 then
restoreSpeed() setSpeedPhysicsExemption(false) return end
local target = runtime.savedWalkSpeed
if runtime.speedHumanoid ~= humanoid or type(target) ~= "number" or target < 0 then
runtime.savedWalkSpeed = nil runtime.speedHumanoid = nil runtime.speedLastWritten = nil
setSpeedPhysicsExemption(false) return end local starting = humanoid.WalkSpeed
